return ['domain'=>'lingua-forge','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'tr_TR','project-id-version'=>'Lingua Forge 2.1.0','pot-creation-date'=>'2026-07-21T23:33:36+00:00','po-revision-date'=>'2026-07-05 23:40+0000','x-generator'=>'Loco https://localise.biz/','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Çok dilli yönlendirme, tam çok dilli SEO (hreflang, Open Graph, Schema.org, site haritası), ve WordPress için AI içerik araçları. Dil tespiti, URL yönlendirme, çeviri, içerik oluşturma ve tam bir SEO katmanı — ek bir eklenti gerekmez.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Çevir','Lingua Forge — Quick Translate'=>'Lingua Forge — Hızlı Çeviri','Informative'=>'Bilgilendirici','Persuasive'=>'İkna edici','Storytelling'=>'Hikaye Anlatımı','Technical'=>'Teknik','Conversational'=>'Konuşma Dili','Permission denied.'=>'İzin reddedildi.','Cannot determine target language from slug.'=>'Hedef dili slug\'dan belirlenemiyor.','Invalid post type.'=>'Geçersiz gönderi türü.','Invalid or primary language.'=>'Geçersiz veya ana dil.','Template not found or not stored in the database.'=>'Şablon bulunamadı veya veritabanında saklanmadı.','Template has no content.'=>'Şablonun içeriği yok.','No internal links found to update.'=>'Güncellenecek dahili bağlantı bulunamadı.','%d link updated.'=>'%d bağlantı güncellendi.' . "\0" . '%d bağlantı güncellendi.','No language-specific template parts found to map.'=>'Haritalanacak dil\'e özgü şablon parçası bulunamadı.','No template part references needed updating.'=>'Güncellenecek şablon parçası referansı yok.','%d part reference updated.'=>'%d parça referansı güncellendi.' . "\0" . '%d parça referansı güncellendi.','Invalid language.'=>'Geçersiz dil.','Template part not found or not stored in the database.'=>'Şablon parçası bulunamadı veya veritabanında saklanmadı.','Template part has no content.'=>'Şablon parçasının içeriği yok.','No navigation references needed updating.'=>'Güncellenecek gezinme referansı yok.','%d navigation reference updated.'=>'%d gezinme referansı güncellendi.' . "\0" . '%d gezinme referansı güncellendi.','No AI provider configured.'=>'AI sağlayıcısı yapılandırılmadı.','Missing pattern name or language.'=>'Desen adı veya dil eksik.','Pattern not found.'=>'Desen bulunamadı.','Pattern has no content to translate.'=>'Desenin çevrilecek içeriği yok.','AI provider returned an empty response.'=>'AI sağlayıcısı boş yanıt döndürdü.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Desen çevrildi ve kaydedildi. İçeriği blok düzenleyici Desen ekleyicisi aracılığıyla CPT gönderinize yapıştırın veya Yeniden Kullanılabilir Blok için başlangıç noktası olarak kullanın.','%d template repaired.'=>'%d şablon onarıldı.' . "\0" . '%d şablonlar onarıldı.','All template metadata is already up to date.'=>'Tüm şablon meta verisi zaten güncel.','Invalid template type.'=>'Geçersiz şablon türü.','Template "%s" already exists.'=>'"%s" zaten var.','Fix Links'=>'Bağlantıları Düzelt','Fix Parts'=>'Parçaları Düzelt','Re-create'=>'Yeniden Oluştur','"%s" recreated.'=>'"%s" yeniden oluşturuldu.','"%s" created.'=>'"%s" oluşturuldu.','Invalid template part.'=>'Geçersiz şablon parçası.','Template part "%s" already exists.'=>'"%s" şablon parçası zaten var.','Fix Nav'=>'Gezintiyi Düzelt','"%1$s" recreated. %2$d template updated.'=>'"%1$s" yeniden oluşturuldu. %2$d şablon güncellendi.' . "\0" . '"%1$s" yeniden oluşturuldu. %2$d şablon güncellendi.','"%1$s" created. %2$d template updated.'=>'"%1$s" oluşturuldu. %2$d şablon güncellendi.' . "\0" . '"%1$s" oluşturuldu. %2$d şablon güncellendi.','Page'=>'Sayfa','Single'=>'Tek','Search'=>'Arama','Search Results'=>'Arama Sonuçları','Archive'=>'Arşiv','Front Page'=>'Ana Sayfa','Blog Home'=>'Blog Ana Sayfası','Single: %s'=>'Tek: %s','Single %s'=>'Tek %s','Archive: %s'=>'Arşiv: %s','%s Archive'=>'%s Arşivi','No source content found to translate.'=>'Çeviri yapılacak kaynak içerik bulunamadı.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Çevirildi. Site Düzenleyici\'de inceleyin — dahili bağlantılar, gezinme URL\'leri ve şablon slug\'ları otomatik olarak güncellenmez.','Navigation not found.'=>'Gezinme bulunamadı.','Navigation has no content to translate.'=>'Gezinmenin çevrilecek içeriği yok.','"%1$s %2$s" saved.'=>'"%1$s %2$s" kaydedildi.','SEO Analysis'=>'SEO Analizi','Profile'=>'Profil','Details ↗'=>'Detaylar ↗','/ 100'=>'/ 100','Overall SEO score'=>'Genel SEO skoru','Metric'=>'Metrik','Finding'=>'Bulma','Title'=>'Başlık','Meta description'=>'Meta açıklama','Word count'=>'Kelime sayısı','Reading time'=>'Okuma süresi','Headings'=>'Başlıklar','Images'=>'Görseller','Links'=>'Bağlantılar','AI Recommendations'=>'Yapay Zeka Önerileri','Run AI Analysis'=>'AI Analizi Çalıştır','Analyzing…'=>'Analiz ediliyor…','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Yapay Zeka tabanlı önerileri etkinleştirmek için Ayarlar → API Anahtarları\'nda bir AI sağlayıcısı yapılandırın.','AI analysis failed. Please try again.'=>'Yapay zeka analizi başarısız oldu. Lütfen tekrar deneyin.','Suggested title'=>'Önerilen başlık','Suggested meta description'=>'Önerilen meta açıklama','Loaded from cache.'=>'Önbellekten yüklendi.','↺ Refresh AI Analysis'=>'↺ AI Analizini Yenile','Analyse…'=>'Analiz et…','Analysis request failed. Please try again.'=>'Analiz isteği başarısız oldu. Lütfen tekrar deneyin.','No translation found — analyzed the source language version.'=>'Çeviri bulunamadı — kaynak dil sürümünü analiz etti.','Translate page…'=>'Sayfayı çevir…','Generate content…'=>'İçerik oluştur…','AI Behaviour Preset'=>'Yapay Zeka Davranış Ön Ayarı','Custom'=>'Özel','Global default (%s)'=>'Global varsayılan (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Bu sayfadaki Çeviri ve İçerik Oluşturma için Yapay Zeka ön ayarını geçersiz kılar. Site genelinde özel istem talimatları (Ayarlar → Davranış) her isteğe eklenir, bu seçimden bağımsızdır.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Bu sayfadaki Çeviri ve İçerik Oluşturma için Yapay Zeka ön ayarını geçersiz kılar. Diğer tüm özellikler her zaman küresel ön ayarı kullanır.','Close'=>'Kapat','Translate missing'=>'Eksik çeviriyi çevir','From'=>'İle','Retranslate'=>'Yeniden çevir','Retranslate every other language version from this post. Creates any that are missing and overwrites any that already exist — including the primary language, if this post is a translation.'=>'Bu yazıyı diğer tüm dil sürümlerine yeniden çevirin. Eksik olanları oluşturun ve varolan olanları üzerine yazın — bu yazı bir çeviri ise birincil dili de içerir.','Sync'=>'Senkronize Et','Reassign the correct language-specific template to every existing translation of this post. No AI call and no content changes — free and safe to run any time.'=>'Bu yazının her mevcut çevirisine doğru dile özel şablonu yeniden atayın. İçerik değişikliği olmaz ve AI çağrısı yapılmaz — her zaman çalıştırmak için güvenli ve ücretsizdir.','Template Sync — reassign templates for every translation'=>'Şablon Senkronizasyonu — her çeviri için şablonları yeniden atayın','TS'=>'ŞS','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'Son kural tabanlı SEO skoru. Güncellemek için Ayarlar → SEO → Analiz bölümünde analiz yapın.','Translating…'=>'Çeviriliyor…','Retranslating…'=>'Yeniden çeviriliyor…','Syncing…'=>'Senkronize ediliyor…','This retranslates every other language version of this post from this one — creating any that are missing and overwriting any that already exist (including the primary language, if this post is a translation). This cannot be undone. Continue?'=>'Bu, bu yazının diğer tüm dil sürümlerini bu yazıdan yeniden çevirir — eksik olanları oluşturacak ve mevcut olanların üzerine yazacaktır (bu yazı bir çeviri ise birincil dili de içerir). Bu işlem geri alınamaz. Devam edilsin mi?','Syncing templates…'=>'Şablonlar senkronize ediliyor…','✓ Done'=>'✓ Tamamlandı','Error'=>'Hata','Navigation posts are translated via the Router tab, not this button.'=>'Gezinme gönderileri, bu düğme yerine Router sekmesi aracılığıyla çevrilir.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'"%s" gönderi türü için çeviri oluşturmak, aktif bir entegrasyon gerektirir. Lütfen gerekli entegrasyonun yüklü ve aktif olduğundan emin olun.','No %s version found in this translation group.'=>'Bu çeviri grubunda %s sürümü bulunamadı.','Sync from a secondary-language WooCommerce product is disabled by default, since it would overwrite the primary product. Enable it in Settings → Behavior → WooCommerce if you want a translation to be able to become the new source content.'=>'İkincil dildeki WooCommerce ürününden Senkronize Et varsayılan olarak devre dışı bırakılmıştır, çünkü birincil ürünün üzerine yazılır. Bir çevirinin yeni kaynak içeriği olabilmesini istiyorsanız Ayarlar → Davranış → WooCommerce\'te etkinleştirin.','Sync from a secondary-language post is disabled by default, since it would overwrite the primary post. Enable it in Settings → Behavior → Sync if you want a translation to be able to become the new source content.'=>'İkincil dildeki yazıdan Senkronize Et varsayılan olarak devre dışı bırakılmıştır, çünkü birincil yazının üzerine yazılır. Bir çevirinin yeni kaynak içeriği olabilmesini istiyorsanız Ayarlar → Davranış → Senkronize Et\'te etkinleştirin.','Skipped — you do not have permission to edit the existing translation.'=>'Atlandı — mevcut çeviriyi düzenlemek için izniniz yoktur.','Creating translations for post type "%s" requires an active integration.'=>'"%s" yazı türü için çeviriler oluşturmak etkin bir entegrasyon gerektirir.','Template Sync can only be run from the primary/source-language post.'=>'Şablon Senkronizasyonu yalnızca birincil/kaynak dil yazısından çalıştırılabilir.','Skipped — you do not have permission to edit this translation.'=>'Atlandı — bu çeviriyi düzenlemek için izniniz yoktur.','Translation Caching'=>'Çeviri Önbellekleme','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge, gereksiz AI API çağrılarını önlemek için iki bağımsız önbellek katmanı kullanır. Her birini incelemek ve yönetmek için aşağıdaki sekmeleri kullanın.','API Response Cache'=>'API Yanıt Önbelleği','Translation Memory'=>'Çeviri Belleği','(disabled)'=>'(devre dışı)','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'AI tarafından oluşturulan çeviriler, meta açıklamalar, alıntılar ve içerik için gönderi başına önbellek. Girişler, içerik veya AI sağlayıcısı/model değiştiğinde otomatik olarak geçersiz kılınır.','Enable API response caching'=>'API yanıt önbelleklemesini etkinleştir','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'API Yanıt Önbelleği, her AI isteğinin ham sonucunu saklar — çeviri, meta açıklama, alıntı ve içerik üretimi — girişlerin karma değeriyle anahtarlandırılır (içerik, dil çifti, sağlayıcı, model). İstek ayarlarını optimize ederken veya her isteğin AI sağlayıcısına ulaşmasını istediğinizde devre dışı bırakın. Devre dışı bırakmak, önbelleğe alınmış girişleri silmez — yeniden etkinleştirme onları geri yükler.','Save'=>'Kaydet','Cached API responses'=>'Önbelleğe alınmış API yanıtları','API calls saved by cache'=>'Önbelleğe alınmış API çağrıları','(avg %.1f hits/entry)'=>'(ortalama %.1f vuruş/entry)','Oldest cached response'=>'En eski önbelleğe alınmış yanıt','Most recent cached response'=>'En son önbelleğe alınmış yanıt','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Tüm önbelleğe alınmış AI sonuçlarını temizlesin mi? Gelecekteki istekler, önbellek yeniden oluşturulana kadar yeni API çağrılarını tetikleyecektir.','Clear API Response Cache'=>'API Yanıt Önbelleğini Temizle','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'Gönderiler arasında paylaşılan blok seviyesinde çeviri önbelleği. Etkinleştirildiğinde, aynı bloklar (aynı işaretleme, dil çifti ve sözlük) bellekte saklanır ve yapay zekaya tekrar çağrı yapılmaz. Sözlük düzenlemeleri ve Uyumluluk ön ayar değişiklikleri otomatik olarak etkilenen önbelleğe alınmış çevirileri geçersiz kılar.','Enable block-level translation cache reuse across posts'=>'Blok seviyesinde çeviri önbelleği yeniden kullanımını etkinleştir','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Şu anda, blok-yorum öznitelik yer tutucuları (wp:details özet alanları vb.) kullanan yazılar için atlanır — bunlar mevcut tek çağrı çeviri yoluna geçer.','Cached block translations'=>'Önbelleğe alınmış blok çevirileri','Block translation reuses'=>'Blok çeviri tekrarlarını','(avg %.1f hits/block)'=>'(ortalama %.1f erişim/blok)','Oldest cached block'=>'En eski önbelleğe alınmış blok','Most recent cached block'=>'En son önbelleğe alınmış blok','Approximate size'=>'Yaklaşık boyut','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Tüm Çeviri Belleğini temizle? Gelecekteki çeviriler önbelleği yeniden oluşturacaktır.','Clear Translation Memory'=>'Çeviri Belleğini Temizle','API Response Cache setting saved.'=>'API Yanıt Önbellek ayarı kaydedildi.','Translation Memory setting saved.'=>'Çeviri Belleği ayarı kaydedildi.','AI cache cleared. %d entry was removed.'=>'AI önbelleği temizlendi. %d giriş kaldırıldı.' . "\0" . 'AI önbelleği temizlendi. %d giriş kaldırıldı.','Translation Memory cleared. %d cached block was removed.'=>'Çeviri Belleği temizlendi. %d önbelleğe alınmış blok kaldırıldı.' . "\0" . 'Çeviri Belleği temizlendi. %d önbelleğe alınmış blok kaldırıldı.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge, eksiksiz çok dilli SEO çözümüdür. Ek bir SEO eklentisi gerekmez.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Genel bir SEO eklentisi yüklü ise, bu panel LF\'nin nasıl çakışmayı önlediğini gösterir. Amaç çakışma önlemektir — işbirliği değil. LF her zaman çok dilli SEO katmanını sağlar (hreflang, og:locale, inLanguage şeması) ve doğru üretim için LF\'nin dil yönlendirme yapılandırmasını bilmesi gerekir.','Installed SEO plugins'=>'Yüklenmiş SEO eklentileri','Plugin'=>'Eklenti','Status'=>'Durum','✓ Active'=>'✓ Aktif','— Not detected'=>'— Algılanmadı','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Çakışan SEO eklentisi tespit edilmedi. Lingua Forge, tüm SEO çıktısını bağımsız olarak yönetiyor.','What LF provides — and collision avoidance'=>'Sağladıklarımız — ve çakışma önleme','Feature'=>'Özellik','LF provides'=>'LF sağlar','When another SEO plugin is installed'=>'Başka bir SEO eklentisi yüklendiğinde','Hreflang'=>'Hreflang','Disabled (by setting)'=>'Devre dışı (ayarla)','✓ LF outputs — plugin hreflang suppressed'=>'✓ LF çıktıları — eklenti hreflang devre dışı bırakıldı','✓ LF outputs'=>'✓ LF çıktıları','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF, x-default dahil olmak üzere yapılandırılmış her dil için doğru hreflang çıkışı sağlar. Genel SEO eklentileri, LF yönlendirme yapılandırmanıza erişemez ve yanlış URL varsayımlarıyla hreflang üretir. LF, çakışmaları önlemek için filtre aracılığıyla bunların çıktısını engeller.','Suppressed: %s.'=>'Engellendi: %s.','Open Graph'=>'Open Graph','Disabled (mode setting)'=>'Devre dışı (mod ayarı)','→ Locale tags only — deferring base OG to plugin'=>'→ Yalnızca Yerel etiketler — temel OG\'yi eklentiye devret','→ Locale tags only (manual setting)'=>'→ Yalnızca Yerel etiketler (manuel ayar)','✓ LF outputs full OG + Twitter Cards'=>'✓ LF çıktıları tam OG + Twitter Kartları','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF her zaman og:locale ve og:locale:alternate ekler — çok dilli OG sinyalleri, hiçbir genel SEO eklentisinin doğru şekilde üretemeyeceği. Temel OG seti (og:title, og:description, og:image) başka bir eklenti yoksa çıktı verir. Bir SEO eklentisi yüklüyse, LF temel seti atlar ve yinelenen etiketleri önler — bu, eklentinin "daha iyi" olması değil, yinelenmenin değer üretmemesidir.','Schema.org JSON-LD'=>'Schema.org JSON-LD','— Deferred to plugin'=>'— Eklentiye devredildi','✓ LF outputs Article / WebPage / WebSite'=>'✓ LF çıktıları Makale / WebSayfası / WebSitesi','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF, inLanguage açıklamalarıyla çok dilli JSON-LD çıktısı verir ve bu açıklamalar dil yönlendirme yapılandırmasına bağlıdır. Bir SEO eklentisi kurulduğunda, LF kendi şemasını tamamen devre dışı bırakır: yinelenen JSON-LD grafikleri doğrulama hataları üretir ve mevcut bir grafiği tamamlamak için temiz bir yol yoktur.','XML Sitemap'=>'XML Site Haritası','✓ Active at /lf-sitemap.xml'=>'✓ /lf-sitemap.xml\'de Aktif','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF, tüm çeviri grupları için xhtml:link alternatifi ile kendi site haritasını oluşturur. Bir SEO eklentisi yüklüyse, ayrı bir site haritası oluşturur — ikisi bağımsız olarak var olur. Her ikisini de Google Search Console\'a gönderin: içerik keşfi için SEO eklentisi site haritası, dil ilişkisi sinyalleri için LF site haritası.','Canonical tag'=>'Kanonik etiket','✓ WP canonical replaced (self-referencing)'=>'✓ WP canonical değiştirildi (kendi kendine referanslı)','WP core canonical active (hreflang disabled)'=>'WP çekirdek canonical aktif (hreflang devre dışı)','LF removes the WordPress core canonical tag and replaces it with a self-referencing canonical pointing to the correct language-prefixed URL. When a third-party SEO plugin (Yoast, Rank Math, AIOSEO, SEOPress) is active, LF defers canonical management to that plugin entirely.'=>'LF, WordPress çekirdek canonical etiketini kaldırır ve doğru dil öneki URL\'sine işaret eden kendine referans veren canonical ile değiştirir. Üçüncü taraf bir SEO eklentisi (Yoast, Rank Math, AIOSEO, SEOPress) etkinse, LF canonical yönetimini tamamen bu eklentiye devreder.','Legacy lf-social-share mu-plugin'=>'Klasik lf-social-share mu eklentisi','The lf-social-share mu-plugin is active.'=>'lf-social-share mu eklentisi aktif.','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Lingua Forge\'un yerleşik Sosyal Paylaşım ve Open Graph modülleri, mu-eklentisinin sağladığı tüm işlevselliği kapsar ve çok dilli og:locale desteği de dahil. Mu-eklentisini güvenle devre dışı bırakabilirsiniz.','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'OG/Twitter Kart etiketleri: LF\'nin Open Graph modülü tarafından yönetilir (SEO → Open Graph & Twitter Cards)','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Sosyal İkonlar bloğu paylaşımı: URL\'ler: LF\'nin yerleşik Sosyal Paylaşım (SEO → Sosyal Paylaşım) tarafından yönetilir','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'kopya/yapılandırıcı/otomatik JS eylemleri: LF\'nin sosyal-paylaşım.js tarafından işlenir','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Aktifken, mu eklentisi temel OG setini yönetir ve LF yalnızca yerel ayar etiketleri (otomatik mod) üretir. Kaldırmak, LF\'yi otomatik olarak tam OG moduna geçirir.','Debug Files'=>'Hata Ayıklama Dosyaları','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Hata ayıklama günlüğü etkinleştirildiğinde (aşağıdaki anahtar veya wp-config.php\'de LINGUAFORGE_AI_DEBUG tanımlanarak), Çeviri ve FSE şablon çeviri özellikleri sorun giderme için ham AI istemlerini ve yanıtlarını diske yazar. Bu bölümü, çıktıyı izlemek ve ihtiyacınız olanı aldıktan sonra temizlemek için kullanın — dosyalar büyük sayfalarda hızla büyüyebilir. Hedef dizini linguaforge_debug_dir filtresi aracılığıyla yapılandırın.','Debug files cleared. %d file was removed.'=>'Hata ayıklama dosyaları temizlendi. %d dosya kaldırıldı.' . "\0" . 'Hata ayıklama dosyaları temizlendi. %d dosya kaldırıldı.','Debug logging enabled.'=>'Hata ayıklama günlüğü etkinleştirildi.','Debug logging disabled.'=>'Hata ayıklama günlüğü devre dışı bırakıldı.','Debug logging'=>'Hata ayıklama günlüğü','Write AI prompts and responses to disk for troubleshooting'=>'Sorun giderme için AI istemlerini ve yanıtlarını diske yazın','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php\'deki LINGUAFORGE_AI_DEBUG sabiti tarafından ZORUNLU olarak AÇILDI. Bu anahtarı kaldırın, böylece buradan bu anahtarı kontrol edebilirsiniz.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php\'deki LINGUAFORGE_AI_DEBUG sabiti tarafından ZORUNLU olarak KAPATILDI. Bu anahtarı kaldırın, böylece buradan bu anahtarı kontrol edebilirsiniz.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Dosyalar aşağıdaki dizine kaydedilir. Çeviri sorunlarını teşhis etmek için kullanışlıdır — ihtiyacınız olanı aldıktan sonra kapatın, böylece dosyalar birikmez. Ayrıca wp-config.php\'den `define( \'LINGUAFORGE_AI_DEBUG\', true );` ile zorlayabilirsiniz, bu da anahtarı geçersiz kılar.','Currently:'=>'Şu anda:','✓ Enabled'=>'✓ Etkin','✗ Disabled'=>'✗ Devre Dışı','Directory'=>'Dizin','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Hata ayıklama çıktısını gizli olmayan bir konuma yönlendirmek için linguaforge_debug_dir filtresi ile kullanın.','Files'=>'Dosyalar','.txt file(s) in the directory'=>'.txt dosyası(ları) dizinde','Save Debug Setting'=>'Hata ayıklama Ayarını Kaydet','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Hata ayıklama dizinindeki tüm .txt dosyalarını silmek istiyor musunuz? Dizin kendisi kalacak, böylece gelecekteki hata ayıklama yazıları düzgün şekilde kaydedilir.','Clear Debug Files'=>'Hata ayıklama Dosyalarını Temizle','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge, her sayfa için yapılandırılmış her dil için <link rel="alternate" hreflang> etiketleri çıkarır ve kaynak dile işaret eden x-default dahil edilir. Bu, Google ve diğer arama motorları için birincil çokdillilik SEO sinyalidir — ek SEO eklentisi gerekmez.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Yoast SEO, Rank Math, All in One SEO veya SEOPress aktifse, Lingua Forge otomatik olarak onların hreflang çıkışını filtre aracılığıyla engeller. Genel SEO eklentileri, tek dil URL yapısına dayalı hreflang üretir ve çokdilliliğinizi dikkate alamaz; LF\'nin çıktısı her zaman doğrudur.','Hreflang settings saved.'=>'Hreflang ayarları kaydedildi.','Hreflang output'=>'Hreflang çıktısı','Output hreflang tags in wp_head'=>'wp_head\'de hreflang etiketleri çıkışı','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Sadece headless siteler veya tamamen özelleştirilmiş hreflang uygulamaları için devre dışı bırakın. Devre dışı bırakıldığında, LF artık WordPress çekirdek canonical etiketini kaldırmaz ve SEO eklentisinin hreflang çıktısını engellemez.','Current status'=>'Mevcut durum','✓ Hreflang active'=>'✓ Hreflang aktif','LF is outputting hreflang tags and is replacing the WordPress core canonical with a self-referencing canonical for each language version.'=>'LF, hreflang etiketlerini çıkartıyor ve WordPress çekirdek canonical\'ını her dil sürümü için kendi kendine referans veren bir canonical ile değiştiriyor.','LF is suppressing hreflang output from: %s'=>'LF, şu etiketlerin hreflang çıktılarını engelliyor: %s','Save Hreflang Settings'=>'Hreflang Ayarlarını Kaydet','Language Overrides'=>'Dil Üzerinden Değişiklikleri','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Üçüncü taraf eklenti dizelerini geçersiz kılmak için derlenmiş .mo dosyalarını yükleyin — örneğin, "oda" yerine "daire" kullanan özel VikBooking çevirisi. Dosyalar WordPress adlandırma kurallarına uygun olmalı: {textdomain}-{locale}.mo (örneğin, vikbooking-ca.mo). Yükleme klasöründe saklanır ve eklenti güncellemelerine dayanır.','Override file uploaded successfully.'=>'Geçersiz kılma dosyası başarıyla yüklendi.','Override file deleted.'=>'Geçersiz kılma dosyası silindi.','No file was selected.'=>'Hiç dosya seçilmedi.','Only .mo files are accepted.'=>'Sadece .mo dosyaları kabul edilir.','The upload failed — please try again.'=>'Yükleme başarısız oldu — lütfen tekrar deneyin.','Could not save the file. Check that the uploads folder is writable.'=>'Dosya kaydedilemedi. Yükleme klasörünün yazılabilir olup olmadığını kontrol edin.','Invalid filename.'=>'Geçersiz dosya adı.','Security check failed — file path is not permitted.'=>'Güvenlik kontrolü başarısız — dosya yolu izin verilmedi.','An unknown error occurred.'=>'Bilinmeyen bir hata oluştu.','Text domain / locale'=>'Dil alanı / yerel ayar','Size'=>'Boyut','Delete all files for this override (both .mo and .po)?'=>'Bu geçersiz kılma için tüm dosyaları silmek istiyor musunuz? (hem .mo hem de .po)','Delete'=>'Sil','No override files uploaded yet.'=>'Henüz geçersiz kılma dosyası yüklenmedi.','Upload .mo file'=>'.mo dosyası yükle','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Sadece derlenmiş .mo dosyalarını kabul eder. Dosya adı {textdomain}-{locale}.mo kalıbını takip etmelidir. Aynı isimdeki bir dosya yüklemek onu değiştirecektir.','Upload Override'=>'Geçersiz kılma yükle','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Güvenli Depolamaya Kopyala','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate, özel çevirilerini wp-content/languages/loco/ dizininde saklar — bu konum, WP çekirdek güncellemesi, eklenti yeniden yüklemesi veya Loco Translate\'in kaldırılmasıyla sessizce silinebilir. Dosyaları buraya kopyalamak, bunları Lingua Forge i18n-overrides dizinine taşır ve bu dizin tüm bu olaylar sırasında kalıcıdır ve her istekte otomatik yüklenir.','File copied to safe storage successfully.'=>'Dosya güvenli depolamaya başarıyla kopyalandı.','Source file not found.'=>'Kaynak dosya bulunamadı.','Could not copy the file. Check that the uploads folder is writable.'=>'Dosya kopyalanamadı. Yükleme klasörünün yazılabilir olup olmadığını kontrol edin.','Invalid file reference.'=>'Geçersiz dosya referansı.','Type'=>'Tür','✓ In safe storage'=>'✓ Güvenli depolamada','Copy to safe storage'=>'Güvenli depolamaya kopyala','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Henüz özel Loco Translate dosyası bulunmuyor. Bir çeviri kaydettiğinizde burada görünürler.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge, Open Graph ve Twitter Kart meta etiketleri çıkarır, böylece paylaşılan URL\'ler sosyal platformlarda doğru dil, başlık, açıklama ve resmi gösterir.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'Hreflang\'den farklı olarak — LF her zaman diğer eklentileri geçersiz kılar çünkü çokdilliliğinizi bilemezler — Open Graph farklıdır: Yoast, Rank Math ve benzeri eklentiler zaten içeriğiniz için doğru OG etiketleri üretir. Bunları çoğaltmak değer katmaz. Otomatik modda, LF aktif SEO eklentilerini tespit eder ve yalnızca sağlayamayacakları öğeleri ekler: og:locale (mevcut dil) ve og:locale:alternate (diğer yapılandırılmış diller).','Open Graph settings saved.'=>'Open Graph ayarları kaydedildi.','Open Graph output'=>'Open Graph çıkışı','Output Open Graph tags in wp_head'=>'wp_head\'de Open Graph etiketleri çıkışı','Output mode'=>'Çıkış modu','Auto (recommended)'=>'Otomatik (önerilen)','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Çalışma zamanında aktif SEO eklentilerini (Yoast, Rank Math vb.) tespit edin. Başka bir eklenti zaten tam OG setini çıktı veriyorsa yalnızca og:locale + og:locale:alternate yayın; hiç biri tespit edilmezse tam seti yayın.','Locale only'=>'Yalnızca Yerel','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Her zaman yalnızca og:locale ve og:locale:alternate yayınla. Diğer bir eklenti veya tema tam OG setini yönetiyorsa kullanın.','Full'=>'Tam','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Diğer eklentilerden bağımsız olarak her zaman tam OG + Twitter Kartı setini yayınla. Sadece başka eklentilerin OG etiketleri çıkarmadığı durumlarda kullanın.','Disabled'=>'Devre dışı','Do not output any OG tags.'=>'Herhangi bir OG etiketi çıkarmayın.','Default OG image'=>'Varsayılan OG resmi','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'Bir sayfada öne çıkan görsel, site logosu veya site simgesi yoksa kullanılan yedek resim URL\'si. Arşivler, blog dizini ve küçük resmi olmayan herhangi bir tekil sayfa için sosyal önizlemede gösterilir.','— Disabled'=>'— Devre dışı','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Aktif — yalnızca yerel etiketler (og:locale, og:locale:alternate)','✓ Active — full OG + Twitter Cards'=>'✓ Aktif — tam OG + Twitter Kartları','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Klasik lf-social-share mu eklentisi tespit edildi. LF, temel OG setini mu eklentisine devrediyor ve yalnızca og:locale + og:locale:alternate çıktı veriyor. Mu eklentisini devre dışı bırakabilirsiniz — LF\'nin yerleşik Sosyal Paylaşım (SEO → Sosyal Paylaşım sekmesi) ve Open Graph aynı işlevselliği kapsar.','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'Algılanan SEO eklentisi: %s. LF, yalnızca og:locale ve og:locale:alternate çıkartıyor; algılanan eklenti tam OG setini yönetir.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Dış OG eklentisi tespit edilmedi. LF, tam OG + Twitter Kart setini çıkarıyor.','Save Open Graph Settings'=>'Open Graph Ayarlarını Kaydet','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge, Schema.org JSON-LD yapılandırılmış verileri çıkarır, böylece arama motorları içeriğinizin türünü, dilini ve meta verilerini anlar. Bu, çok dilli içerikler için inLanguage açıklamalarını Google ve diğer tarayıcılar ile iletişim kurmanın temel yoludur.','Schema output deferred.'=>'Schema çıkışı ertelendi.','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s etkin ve zaten Schema.org JSON-LD çıktı veriyor. Lingua Forge kendi şema çıktısını devre dışı bıraktı, çakışan grafiklerin önüne geçmek için. Open Graph\'tan farklı olarak — LF başka bir eklentinin çıktısının üzerine og:locale ekler — şema temizce tamamlanamaz: yinelenen veya örtüşen JSON-LD grafikler doğrulama hataları üretir. Yapılandırılmış veriyi LF\'nin işlemesini istiyorsanız, algılanan eklentide şema çıkışını devre dışı bırakın.','Schema.org settings saved.'=>'Schema.org ayarları kaydedildi.','Schema.org output'=>'Schema.org çıkışı','Output Schema.org JSON-LD in wp_head'=>'WP_head\'da Schema.org JSON-LD Çıkışı','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Kilitlendi — çakışan bir SEO eklentisi aktif. Yukarıdaki bildirime bakın.','Article / WebPage'=>'Makale / Web Sayfası','Output Article or WebPage schema on singular posts and pages'=>'Tekil gönderiler ve sayfalarda Makale veya WebSayfası şeması çıkışı','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Blog gönderileri Makale kullanır; diğer tüm gönderi türleri ve sayfalar WebSayfası kullanır. Başlık, açıklama, inLanguage, url, yayın tarihi, güncelleme tarihi, resim ve yayıncıyı içerir.','WebSite'=>'Web Sitesi','Output WebSite schema on the front page and blog index'=>'Ana sayfa ve blog dizininde WebSite şemasını çıkart','Includes site name, url, and inLanguage.'=>'Site adı, url ve inLanguage içerir.','Product'=>'Ürün','Output Product schema on WooCommerce product pages'=>'WooCommerce ürün sayfalarında Ürün şeması çıkışı','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'İsim, açıklama, inLanguage, url, resim ve fiyat, fiyatParaBirimi ve kullanılabilirlik içeren Teklif. Fiyat ve kullanılabilirlik, kaynak dil ürününden (paylaşılan stok modeli) gelir.','Currently emitting'=>'Şu anda yayınıyor','Article / WebPage — all singular posts and pages'=>'Makale / Web Sayfası — tüm tekil gönderiler ve sayfalar','WebSite — front page / blog index'=>'Web Sitesi — ana sayfa / blog dizini','Product — WooCommerce product pages'=>'Ürün — WooCommerce ürün sayfaları','Nothing — all types disabled'=>'Hiçbir şey — tüm türler devre dışı bırakıldı','Save Schema.org Settings'=>'Schema.org Ayarlarını Kaydet','Blog / Editorial'=>'Blog / Editoryal','Product / eCommerce'=>'Ürün / E-ticaret','Landing / Short-form'=>'Açılış / Kısa biçim','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Dil ve gönderi türüne göre filtrele, içeriğinizi gözden geçirin ve herhangi bir öğeye tıklayarak kural tabanlı SEO denetimi yapın — başlık uzunluğu, meta açıklama, kelime sayısı, başlık yapısı, resim alternatif metni kapsamı ve dahili bağlantılar.','Treat H2 as H1 equivalent'=>'H2\'yi H1 eşdeğeri olarak kabul et','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Temanız, gönderi başlığını H1 yerine H2 olarak render ettiğinde etkinleştirin (bazı blok temalarda yaygındır). Analizör, render edilen sayfayı getirir ve H1 bulamazsa H2 bulursa, ilk H2\'yi H1\'ye yükseltir ve puanlama amacıyla kullanır.','Save analysis settings'=>'Analiz ayarlarını kaydet','Per-Post Analysis'=>'Gönderi Başına Analiz','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'Bir gönderiyi seçin ve belirli bir öğe için sonuçları ve puanı görmek üzere detaylı bir SEO denetimi yapın.','Language'=>'Dil','source'=>'kaynak','All types'=>'Tüm türler','Load content'=>'İçeriği yükle','Batch Analysis'=>'Toplu Analiz','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'Tüm yayınlanan gönderiler için bir veya tüm aktif dillerde kapsamlı bir SEO denetimi yapın. Puanlar gönderi başına kaydedilir ve gönderi listesinde Dil sütunu rozetlerinde yansıtılır.','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'WooCommerce sistem sayfaları (Mağaza, Sepet, Ödeme, Hesabım) hariç tutulur — içerikleri WooCommerce tarafından yönetilir ve SEO düzenlemeleriyle geliştirilemez.','Post type'=>'Gönderi türü','Default profile'=>'Varsayılan profil','— Auto-detect —'=>'— Otomatik algıla —','Analyse all languages'=>'Tüm dilleri analiz et','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'Otomatik tespit atamaları: WooCommerce ürünleri → Ürün profili; statik ana sayfa → Açılış profili; diğer her şey → Blog profili. Bu ayarı tüm gönderiler için geçersiz kılmak için belirli bir profil seçin.','%d post'=>'%d gönderi' . "\0" . '%d gönderi','Last run: %s ago'=>'Son çalışma: %s önce','Never run'=>'Asla koşma','avg'=>'ortalama','(partial)'=>'(kısmi)','Analyse'=>'Analiz','(no title) #%d'=>'(başlık yok) #%d','Invalid post ID.'=>'Geçersiz gönderi ID\'si.','Post not found or not published.'=>'Gönderi bulunamadı veya yayınlanmadı.','~%d min read'=>'~%d dakika okuma' . "\0" . '~%d dakika okuma','No title set.'=>'Başlık ayarlanmadı.','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'Başlık %1$d karakter — SERPs\'te kesilmiş olabilir (hedef %2$d altında).','Title is only %d chars — aim for at least 10 characters.'=>'Başlık sadece %d karakter — en az 10 karakter hedefleyin.','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'Tek kelimelik başlık (%d karakter) — ikinci bir kelime eklemek açıklığı ve anahtar kelime kapsamını artırır.','%1$d chars, %2$d words — good title.'=>'%1$d karakter, %2$d kelime — iyi başlık.','Using LF AI meta description.'=>'LF AI meta açıklaması kullanılıyor.','No LF meta description set — using excerpt/content.'=>'LF meta açıklaması ayarlanmadı — özet/metin kullanılıyor.','No meta description found. Generate one via the AI meta description feature.'=>'Meta açıklaması bulunamadı. Bir AI meta açıklaması özelliğiyle oluşturun.','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d karakter — çok kısa (hedef: %2$d–%3$d). %4$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d karakter — SERP\'lerde muhtemelen kesilmiş (%2$d\'nin altında tutun). %3$s','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d karakter — iyi, ideal %2$d\'nin biraz üzerinde ama kabul edilen %3$d-karar aralığında. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d karakter — ideal uzunluk. %2$s','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d kelime — çok az içerik. En az %2$d kelimeye genişletmeyi düşünün.','%1$d words — below recommended minimum of %2$d.'=>'%1$d kelime — önerilen minimum %2$d altında.','%d words.'=>'%d kelime.','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'H2-olarak-H1 modu etkin — başlık H1 eşdeğeri sayılır. (Başlık etiketleri render edilen sayfadan tespit edilemedi; temanızın başlığı doğru şekilde çıkardığından emin olun.)','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'H1 bulunamadı. Genellikle gönderi başlığı H1\'dir — temanızın bunu çıkardığından emin olun.','%d H1 tags found — a page should have exactly one H1.'=>'%d H1 etiketi bulundu — bir sayfada tam olarak bir H1 olmalı.','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1 H1 ✓ — H2 yok, ancak %d H3 alt başlık(lar)ı bulundu (ör. akordeon/detay başlıkları). Yapı kabul edilebilir.','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1 H1 ✓ — kısa içerik (%d paragraf), alt başlıklar gerekmez.','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — H2 alt başlıkları yok (bu içerik türü için kabul edilebilir).','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — H2 veya H3 alt başlıkları bulunamadı. H2 eklenmesi yapıyı iyileştirir.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','No images found in content.'=>'İçerde resim bulunamadı.','%1$d of %2$d image(s) missing alt text.'=>'%1$d / %2$d görüntü(lerin) alt metni eksik.','%d image(s), all have alt text.'=>'%d resim, hepsinin alt metni var.','No links found. Internal links improve crawlability and user navigation.'=>'Bağlantı bulunamadı. Dahili bağlantılar taranabilirliği ve kullanıcı navigasyonunu artırır.','No links found.'=>'Bağlantı bulunamadı.','%d external link(s), no internal links. Add internal links to related content.'=>'%d harici bağlantı, dahili bağlantı yok. İlgili içeriğe dahili bağlantılar ekleyin.','%d external link(s), no internal links.'=>'%d dış bağlantı, iç bağlantı yok.','%1$d internal, %2$d external.'=>'%1$d dahili, %2$d harici.','Post not found.'=>'Gönderi bulunamadı.','No AI provider configured. Add an API key in Settings → API Keys.'=>'AI sağlayıcısı yapılandırılmadı. Ayarlar → API Anahtarları\'nda bir API anahtarı ekleyin.','No response from AI provider. Check your API key and try again.'=>'AI sağlayıcısından yanıt alınamadı. API anahtarınızı kontrol edin ve tekrar deneyin.','AI returned an unexpected response format. Please try again.'=>'Yapay zeka beklenmedik bir yanıt formatı döndürdü. Lütfen tekrar deneyin.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge, /lf-sitemap.xml adresinde, tüm çevrilmiş içeriğiniz için dil alternatif bağlantıları ekleyen özel bir XML site haritası oluşturur. Bu site haritası, WordPress çekirdek site haritasını ve herhangi bir SEO eklentisi site haritasını tamamlar — onları değiştirmez.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'WordPress çekirdek site haritası tüm içerik URL\'lerinizi listeler. LF site haritası, arama motorlarına dil sürümlerinin birbirleriyle nasıl ilişkili olduğunu xhtml:link hreflang alternatifi aracılığıyla gösterir. Tam kapsam için her ikisini de Google Search Console\'a gönderin.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s etkin ve kendi site haritasını oluşturuyor. Bu site haritası LF\'den ayrı. Her ikisi de Google Search Console\'a gönderilmeli: SEO eklentisi site haritası içeriğinizi listeler; LF site haritası çok dilli alternatif bağlantıları ekler. LF\'nin site haritası otomatik olarak robots.txt\'de duyurulur.','Sitemap settings saved.'=>'Site Haritası ayarları kaydedildi.','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Site Haritası önbelleği temizlendi. Bir sonraki ziyaretinizde site haritası URL\'sinde yeniden oluşturulacak.','Sitemap output'=>'Site Haritası çıkışı','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Çok dilli site haritasını /lf-sitemap.xml adresinde oluştur','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Etkinleştirildiğinde, site haritası URL\'si otomatik olarak robots.txt\'de duyurulur ve çevrilmiş içerik kaydedildiğinde önbellek yenilenir.','Sitemap URL'=>'Site Haritası URL\'si','Submit this URL to Google Search Console alongside your main sitemap.'=>'Ana site haritanızla birlikte bu URL\'yi Google Search Console\'a gönderin.','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Henüz oluşturulmadı. Site haritası, site haritası URL\'sine ilk ziyaret sırasında oluşturulur ve 24 saat önbelleğe alınır.','✓ Active — %d URL entry with language alternates'=>'✓ Aktif — %d URL girişi dil alternatifleriyle' . "\0" . '✓ Aktif — %d URL girişi dil alternatifleriyle','No translated content found. The sitemap will populate once posts have been translated.'=>'Çevrilmiş içerik bulunamadı. Gönderiler çevrildikçe site haritası doldurulacaktır.','Last generated: %s'=>'Son oluşturma: %s','Save Sitemap Settings'=>'Site Haritası Ayarlarını Kaydet','Flush Sitemap Cache'=>'Site Haritası Önbelleğini Temizle','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Bir sonraki istekte site haritasını yeniden oluşturmayı zorlar. Toplu içe aktarma veya çeviri ilişkilerini manuel düzenledikten sonra kullanılır.','IndexNow'=>'IndexNow','IndexNow is an open protocol supported by Bing, Yandex, and other search engines. When a translated post is published or updated, Lingua Forge automatically notifies all participating engines in a single push — no polling, no waiting for the next robots.txt crawl.'=>'IndexNow, Bing, Yandex ve diğer arama motorları tarafından desteklenen açık bir protokoldür. Çevirili bir gönderi yayınlandığında veya güncellendiğinde, Lingua Forge otomatik olarak tüm katılımcı motorlara tek bir gönderimde bildirimde bulunur — sorgulama veya bir sonraki robots.txt taramasını bekleme yok.','IndexNow replaces the deprecated Bing and Yandex sitemap-ping endpoints. Google discovers sitemaps via the robots.txt Sitemap: directive as before.'=>'IndexNow, kullanımdan kaldırılan Bing ve Yandex site haritası ping uç noktalarını yerine alır. Google, site haritalarını önceki gibi robots.txt Sitemap: yönergesi aracılığıyla keşfeder.','✓ All URLs submitted to IndexNow successfully.'=>'✓ Tüm URL\'ler başarıyla IndexNow\'ya gönderildi.','No translated URLs found to submit. Publish some translated posts first.'=>'Gönderilecek çevrilmiş URL bulunmamaktadır. Önce bazı çevrilmiş gönderiler yayınlayın.','✗ IndexNow submission failed. Check that the key file is publicly reachable (see below) and try again.'=>'✗ IndexNow gönderimi başarısız oldu. Anahtar dosyasının herkese açık erişilebilir olduğundan emin olun (aşağıya bakın) ve tekrar deneyin.','Verification key'=>'Doğrulama anahtarı','Key file served automatically at: %s'=>'Anahtar dosyası otomatik olarak şu adreste sunulur: %s','Key could not be generated. Check that the site has write access to WordPress options.'=>'Anahtar oluşturulamadı. Site\'nin WordPress seçeneklerine yazma erişimi olduğundan emin olun.','Key file status'=>'Anahtar dosyası durumu','✓ Key file is publicly reachable.'=>'✓ Anahtar dosyası herkese açık erişilebilir.','✗ Key file is not reachable.'=>'✗ Anahtar dosyasına erişilemiyor.','IndexNow engines verify the key file before accepting submissions. If the file is not reachable, submissions will be rejected with a 403 error.'=>'IndexNow motorları, gönderimleri kabul etmeden önce anahtar dosyasını doğrular. Dosya erişilebilir değilse, gönderimler 403 hatasıyla reddedilir.','Common causes: full-page caching (clear it), a security plugin blocking .txt files, or a custom Nginx/Apache rule. The file is served by LF on every request — no physical file is written to disk.'=>'Yaygın nedenler: tam sayfa önbellekleme (temizleyin), .txt dosyalarını engelleyen bir güvenlik eklentisi veya özel Nginx/Apache kuralı. Dosya, LF tarafından her istekte sunulur — disk üzerinde fiziksel bir dosya yazılmaz.','Submit all URLs'=>'Tüm URL\'leri gönder','Submit all URLs via IndexNow'=>'Tüm URL\'leri IndexNow aracılığıyla gönder','Pushes every published, LF-managed URL to IndexNow in one batch. Automatic submission already runs on every publish/update — use this only after a bulk import or when setting up IndexNow for the first time.'=>'Her yayınlanan, LF tarafından yönetilen URL\'yi tek bir toplu işlemde IndexNow\'ya gönderir. Otomatik gönderim, her yayınlama/güncellemede zaten çalışır — bunu yalnızca toplu içe aktarma sonrası veya IndexNow\'u ilk kez kurarken kullanın.','Google does not participate in IndexNow. It discovers sitemaps via the robots.txt Sitemap: directive — which LF has already configured. Use Google Search Console to monitor indexing coverage.'=>'Google, IndexNow\'a katılmaz. Sitemaps\'i robots.txt Sitemap: yönergesi aracılığıyla keşfeder — LF bunu zaten yapılandırmıştır. İndeksleme kapsamını izlemek için Google Search Console\'u kullanın.','Open Search Console →'=>'Açık Arama Konsolu →','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt, Site Haritası yönergesi ile güncellendi.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Fiziksel robots.txt bulundu. LF\'nin Site Haritası yönergesi mevcut.','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Site kökünde fiziksel bir robots.txt dosyası var. WordPress\'in sanal robots.txt\'si — ve LF\'nin Site Haritası: filtre — atlanıyor. LF site haritası arama motorlarına duyurulmaz.','Add Sitemap directive to robots.txt'=>'Robots.txt\'ye Site Haritası yönergesi ekle','Appends the following line to your existing robots.txt: %s'=>'Mevcut robots.txt\'nize aşağıdaki satırı ekler: %s','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS ayarlandı.','Add the following line to your robots.txt manually:'=>'Robots.txt\'ye aşağıdaki satırı manuel olarak ekle:','View current robots.txt'=>'Mevcut robots.txt\'yi görüntüle','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Fiziksel robots.txt dosyası bulunamadı. WordPress sanal olarak oluşturuyor ve LF\'nin Site Haritası yönergesi otomatik olarak dahil edilmiştir.','The following directive is active in your virtual robots.txt:'=>'Aşağıdaki yönerge sanal robots.txt\'nizde aktif durumda:','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Dosya değişiklikleri devre dışı bırakıldı (DISALLOW_FILE_MODS).','Could not write to robots.txt. Check file permissions.'=>'robots.txt\'ye yazılamadı. Dosya izinlerini kontrol edin.','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge, WordPress Çekirdek Sosyal İkonlar bloğunu dinamik paylaşım URL\'leriyle genişletir. Herhangi bir ikonun bağlantısını "share:" değeriyle ayarlayın ve LF, render sırasında doğru paylaşım URL\'sine veya JavaScript eylemine yeniden yazar — özel kod veya üçüncü taraf eklenti gerekmez.','Social Share settings saved.'=>'Sosyal Paylaşım ayarları kaydedildi.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'lf-social-share mu eklentisi aktif. Lingua Forge\'un yerleşik Sosyal Paylaşımı devre dışı — mu eklentisi paylaşım URL\'si yeniden yazma ve JS işlemlerini yönetir.','Social Share'=>'Sosyal Paylaşım','Enable Social Share URL rewriting for Social Icons blocks'=>'Sosyal Simgeler blokları için Sosyal Paylaşım URL yeniden yazma özelliğini etkinleştir','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'lf-social-share mu eklentisi zaten bu özelliği sağladığı için devre dışı bırakıldı.','Save Social Share Settings'=>'Sosyal Paylaşım Ayarlarını Kaydet','How to use'=>'Nasıl kullanılır','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'Blok düzenleyicide, bir Sosyal İkonlar bloğu ekleyin. Her ikon için, bağlantı ayarlarını açın ve aşağıdaki "share:" değerlerinden birini URL olarak girin. Ön yüzde, LF bunu mevcut sayfa için doğru paylaşım URL\'siyle değiştirir.','External share services'=>'Harici paylaşım servisleri','URL to enter'=>'Giriş yapılacak URL','Action'=>'Eylem','Share on Facebook'=>'Facebook\'ta paylaş','Post on X / Twitter'=>'X / Twitter\'da gönder','Share on LinkedIn'=>'LinkedIn\'de paylaş','Send via WhatsApp'=>'WhatsApp aracılığıyla gönder','Send via Telegram'=>'Telegram aracılığıyla gönder','Submit to Reddit'=>'Reddit\'e Gönder','Pin on Pinterest'=>'Pinterest\'te sabitle','Share on Mastodon'=>'Mastodon\'da paylaş','Share via email (mailto:)'=>'E-posta ile paylaş (mailto:)','JavaScript-powered actions'=>'JavaScript destekli eylemler','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Mevcut URL\'yi panoya kopyala. Başarıyla kopyalandığında "Bağlantı kopyalandı" bildirimi gösterir.','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Tarayıcının yerel Web Paylaşım ekranını açın (iOS, Android, bazı masaüstleri). Desteklenmiyorsa panoya kopyalama ile geri döner.','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Mevcutsa yerel paylaşımı kullanın; panoya kopyalamaya geri dönün. "Paylaş" düğmeleri için önerilen varsayılandır.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'Paylaşım URL\'si her zaman mevcut sayfayı yansıtır — manuel URL girişi gerekmez. linguaforge_social_share_url filtresi, herhangi bir hizmet için çözülen URL\'yi geçersiz kılmanıza olanak tanır.','Configuration issue: WP site language has no content on this site'=>'Yapılandırma sorunu: WP site dili bu sitede içeriğe sahip değil','The WordPress site language (%1$s) maps to the language code "%2$s", but no posts on this site are tagged _lf_lang=%2$s. This causes WooCommerce product queries to return zero results, product images to fail, and all language-filtered content queries to break.'=>'WordPress site dili (%1$s) "%2$s" dil koduna eşlenir, ancak bu sitedeki hiçbir yazı _lf_lang=%2$s ile etiketlenmemiştir. Bu, WooCommerce ürün sorgularının sıfır sonuç döndürmesine, ürün görsellerinin başarısız olmasına ve tüm dile göre filtrelenmiş içerik sorgularının bozulmasına neden olur.','Fix: go to'=>'Düzenle: git','Settings → General → Site Language'=>'Ayarlar → Genel → Site Dili','and set it to one of your actual content languages (e.g. %s).'=>'ve bunu gerçek içerik dillerinizden birine ayarlayın (örn. %s).','Environment'=>'Ortam','Lingua Forge version'=>'Lingua Forge sürümü','WordPress version'=>'WordPress sürümü','PHP version'=>'PHP sürümü','Active theme'=>'Aktif tema','(FSE / block theme)'=>'(FSE / blok teması)','(classic theme)'=>'(klasik tema)','URL structure'=>'URL yapısı','Subdomain (de.example.com)'=>'Alt alan adı (de.ornek.com)','Path prefix (/de/)'=>'Yol ön eki (/de/)','WP instance language'=>'WP örneği dili','not a content language — see notice above'=>'içerik dili değil — yukarıdaki bildirime bakın','Primary content language'=>'Birincil içerik dili','Active languages'=>'Aktif diller','PHP max_execution_time'=>'PHP maksimum yürütme süresi','No PHP limit'=>'PHP sınırı yok','(server/FPM timeout still applies)'=>'(sunucu/FPM zaman aşımı hala geçerlidir)','AI translation and batch analysis may time out. Recommend 120s or more.'=>'Yapay zeka çevirisi ve toplu analiz zaman aşımına uğrayabilir. 120 saniye veya daha fazla önerilir.','PHP memory_limit'=>'PHP bellek sınırı','AI Configuration'=>'Yapay Zeka Yapılandırması','(active)'=>'(aktif)','Configured'=>'Yapılandırıldı','No key'=>'Anahtar yok','— AI features are disabled.'=>'— AI özellikleri devre dışı bırakıldı.','Add key →'=>'Anahtar ekle →','Light model'=>'Hafif model','Quality model'=>'Kalite modeli','Active preset'=>'Aktif ön ayar','Daily quota'=>'Günlük kota','Unlimited'=>'Sınırsız','requests / day'=>'günde istek','Permalink Structure'=>'Kalıcı Bağlantı Yapısı','Permalink structure is compatible with Lingua Forge path routing.'=>'Kalıcı bağlantı yapısı, Lingua Forge yol yönlendirmesiyle uyumludur.','Plain permalinks are not supported.'=>'Düz kalıcı bağlantılar desteklenmiyor.','Path routing requires a post-name based permalink structure. Change it in'=>'Yol yönlendirmesi, gönderi adı tabanlı kalıcı bağlantı yapısı gerektirir. Bunu değiştirin in','Settings → Permalinks'=>'Ayarlar → Kalıcı Bağlantılar','Numeric permalink structure is not supported.'=>'Sayısal kalıcı bağlantı yapısı desteklenmiyor.','Switch to a post-name based structure in'=>'Yapıya geçin ve post-ismi tabanlı yapıya geçin in','SEO Plugins'=>'SEO Eklentileri','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'Üçüncü taraf SEO eklentisi tespit edilmedi. Lingua Forge tüm çok dilli SEO çıktısını yönetir.','Active: %s.'=>'Aktif: %s.','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'Tüm özelliklerin davranış tablosu için Ayarlar → SEO → Uyumluluk bölümüne bakın.','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerce aktif değil.','Shop'=>'Mağaza','Cart'=>'Sepet','Checkout'=>'Ödeme','My Account'=>'Hesabım','WooCommerce version'=>'WooCommerce sürümü','Order storage'=>'Sipariş depolama','High-Performance Order Storage (HPOS)'=>'Yüksek Performanslı Sipariş Depolama (HPOS)','Custom tables — LF post-meta filters do not affect orders.'=>'Özel tablolar — LF gönderi-meta filtreleri siparişleri etkilemez.','Shared / compatibility mode'=>'Paylaşılan / uyumluluk modu','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT senkronize edildi — geçici; LF gönderi-meta filtreleri CPT kopyasına uygulanır.','Legacy post-based (CPT)'=>'Klasik gönderi tabanlı (CPT)','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'WP\'deki siparişler — LF yönlendirmesinden shop_order\'un hariç tutulduğundan emin olun.','WcPageBridge active'=>'WcPageBridge aktif','Yes'=>'Evet','No — WooCommerce integration class not loaded'=>'Hayır — WooCommerce entegrasyon sınıfı yüklenmedi','WooCommerce page translations'=>'WooCommerce sayfa çevirileri','No secondary languages configured.'=>'İkincil diller yapılandırılmadı.','Active Plugins'=>'Aktif Eklentiler','No active plugins detected.'=>'Aktif eklenti bulunamadı.','Version'=>'Sürüm','_lf_lang Coverage'=>'_lf_lang Kapsamı','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'_lf_lang olmayan gönderiler, her Lingua Forge dil filtresine görünmez. Bu, içeriğin içe aktarılması veya eklenti etkinleştirilmeden önce oluşturulması durumunda olabilir.','All published posts have a _lf_lang value. No gaps detected.'=>'Tüm yayınlanmış gönderilerin _lf_lang değeri var. Boşluk tespiti yapılmadı.','Missing'=>'Eksik','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'Bu gönderi türünü dil yönlendirmesinden hariç tut — gönderileri artık burada görünmeyecek veya _lf_lang almayacaktır. Bu otomatik olarak geri alınamaz.','Exclude from routing'=>'Yönlendirmeden hariç tut','excluded from routing'=>'yönlendirmeden hariç tutuldu','Destructive action — read before proceeding'=>'Yıkıcı işlem — devam etmeden önce oku','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'Yukarıda listelenen yönlendirilebilir gönderilere _lf_lang = %s ile onarım yapın. Yönlendirme hariç tutulan gönderi türlerindeki gönderilere dokunulmaz. Bu işlemi yalnızca içerik içe aktardıktan veya ilk etkinleştirmeden sonra çalıştırın — toplu dil yeniden atama aracı olarak kullanmayın.','Repair — assign _lf_lang = %s to all routable posts above'=>'Onarım — yukarıdaki tüm yönlendirilebilir gönderilere _lf_lang = %s atayın','Rewrite Rules'=>'Yeniden Yazma Kuralları','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'$wp_rewrite->extra_rules_top\'ta şu anda kayıtlı LF mülkiyetli girişler. 404 hatalarını veya yönlendirme çatışmalarını teşhis etmek için faydalıdır. Hata raporu dosyalarken bunları kopyalayın.','%d rule registered'=>'%d kural kaydedildi' . "\0" . '%d kural kaydedildi','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'LF yeniden yazma kuralları bulunamadı. Bu beklenmedikse kalıcı bağlantıları temizleyin.','Debug Info'=>'Hata ayıklama bilgisi','Copy and paste into a GitHub issue or support request.'=>'Bir GitHub sorunu veya destek talebine kopyala ve yapıştır.','Copy system info'=>'Sistem bilgisi kopyala','Copied!'=>'Kopyalandı!','Repairing…'=>'Onarılıyor…','Repair failed.'=>'Onarım başarısız oldu.','Network error.'=>'Ağ hatası.','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'Bu gönderi türünü dil yönlendirmesinden hariç tut? Gönderileri artık bu listede görünmeyecek veya _lf_lang almayacaktır. Bunu Ayarlar → Yönlendirici → Sorgu Filtreleri Hariç Tutma bölümünden geri alabilirsiniz.','Excluding…'=>'Hariç tutma…','Failed to save exclusion.'=>'Hariç tutmayı kaydetme başarısız oldu.','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d gönderi _lf_lang = %2$s ile etiketlenmiş.' . "\0" . '%1$d gönderi _lf_lang = %2$s ile etiketlenmiş.','Uninstall Behaviour'=>'Kaldırma Davranışı','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Bir yönetici eklentiyi Kaldırmak için Eklentiler → Yüklü Eklentiler → Sil\'den sildiğinde ne olacağını kontrol eder. Eklenti ayarları ve AI önbellekleri her zaman kaldırılır. Dil atamaları ve çeviri ilişkileri varsayılan olarak korunur, böylece yanlışlıkla kaldırma veya yeniden yükleme kaldığı yerden devam edebilir.','Uninstall setting saved.'=>'Kaldırma ayarı kaydedildi.','Delete content data on uninstall'=>'Kaldırma sırasında içerik verilerini sil','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Ayrıca dil atamalarını, çeviri ilişkilerini, meta açıklamaları, sözlüğü ve Çeviri Belleğini kaldırırken, eklenti kaldırılır.','Warning:'=>'Uyarı:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'İşaretlenirse, eklentiyi kaldırmak, bu sitedeki tüm dil atamalarını, çeviri ilişkilerini, meta açıklamaları, sayfa ön ayarlarını, AI sözlüğünü ve Çeviri Belleğini kalıcı olarak silecektir. Bu geri alınamaz. Çok dilli desteği tamamen kaldırmıyorsanız, işaretlemeyin.','Save Uninstall Setting'=>'Kaldırma Ayarını Kaydet','Today'=>'Bugün','Last 7 days'=>'Son 7 gün','Last 30 days'=>'Son 30 gün','All time'=>'Tüm zamanlar','AI Usage'=>'Yapay Zeka Kullanımı','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Özellik, sağlayıcı ve model bazında token kullanımı toplanır. Her başarılı AI çağrısında kaydedilir; Test Bağlantısı pingleeri, toplamları etkilememesi için hariç tutulur.','Check your account, billing, or remaining credits directly on the provider console:'=>'Hesabınızı, faturalandırmanızı veya kalan kredilerinizi doğrudan sağlayıcı konsolundan kontrol edin:','Anthropic Console'=>'Anthropic Konsolu','OpenAI Platform'=>'OpenAI Platformu','Google AI Studio'=>'Google AI Stüdyosu','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Henüz Yapay Zeka kullanımı kaydedilmedi. Bir editör çeviri yaparsa, meta açıklaması oluşturursa veya başka bir Yapay Zeka özelliği kullanırsa, toplamlar burada görünecek.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Seçilen pencerede Yapay Zeka kullanımı kaydı yok (%s). Yukarıdaki daha geniş bir aralık seçin.','Provider'=>'Sağlayıcı','Model'=>'Model','Requests'=>'İstekler','Input tokens'=>'Girdi tokenleri','Output tokens'=>'Çıktı tokenleri','Total tokens'=>'Toplam tokenler','Total'=>'Toplam','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge, Facebook, Pinterest ve benzeri platformlarda ürün URL\'sini paylaşırken doğru ürün tipi, fiyat ve kullanılabilirliği gösteren WooCommerce\'e özgü Open Graph özellikleri ekler.','WooCommerce SEO settings saved.'=>'WooCommerce SEO ayarları kaydedildi.','Product Open Graph'=>'Ürün Open Graph','Add WooCommerce product tags to Open Graph output'=>'Open Graph çıktısına WooCommerce ürün etiketleri ekle','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Etkinleştirildiğinde, Lingua Forge ürün sayfalarında aşağıdaki ek meta etiketlerini üretir: og:type=product, og:price:amount, og:price:currency, og:availability ve Facebook Kataloğu tarafından kullanılan product: isim alanı karşılıkları.','Tags emitted'=>'Yayınlanan etiketler','Tag'=>'Etiket','Value source'=>'Değer kaynağı','"product" (replaces "article")'=>'"ürün" ("makale" yerine kullanılır)','WooCommerce product price'=>'WooCommerce ürün fiyatı','WooCommerce store currency'=>'WooCommerce mağaza para birimi','instock / oos / pending from WC stock status'=>'WC stok durumu ile stokta / tükendi / beklemede','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Fiyat ve kullanılabilirlik her zaman kaynak dil ürününü yansıtır (paylaşılan stok modeli). Etiketler, LF\'nin Open Graph modülü "Tam" veya "Otomatik" modda ayarlandığında ve çakışan SEO eklentisi algılanmadığında çıktı verir.','Save WooCommerce SEO Settings'=>'WooCommerce SEO Ayarlarını Kaydet','AI Provider'=>'AI Sağlayıcısı','AI Usage & Cache'=>'Yapay Zeka Kullanımı ve Önbellek','API Keys'=>'API Anahtarları','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Anahtarlar, WordPress veritabanında saklanmadan önce AES-256-CBC ile şifrelenir. Şifreleme sırrı, WordPress kimlik doğrulama tuzlarınızdan (wp-config.php) türetilir, bu nedenle düz metin anahtarlar asla veritabanına dokunmaz.','API credentials are managed by WordPress in %s. No key is stored by Lingua Forge.'=>'API kimlik bilgileri, %s\'de WordPress tarafından yönetilmektedir. Lingua Forge tarafından herhangi bir anahtar saklanmaz.','Settings → Connectors'=>'Ayarlar → Bağlayıcılar','API Key'=>'API Anahtarı','Paste your API key…'=>'API anahtarınızı yapıştırın…','✓ Configured'=>'✓ Yapılandırıldı','✗ Not configured'=>'✗ Yapılandırılmadı','Test connection'=>'Bağlantıyı test et','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Boş bırakmak mevcut anahtarı korur. Yenisini girerek değiştirebilirsiniz.','Remove stored key'=>'Depolanan anahtarı kaldır','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Bu anahtar şu anda bir sunucu %s tarafından sağlanmaktadır ve burada kaldırılamaz. Üzerine yeni bir anahtar girerek veritabanı değeriyle üzerine yazabilirsiniz.','environment variable'=>'ortam değişkeni','PHP constant'=>'PHP sabiti','Alternative (server-side):'=>'Alternatif (sunucu tarafı):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Anahtarları sabitler veya ortam değişkenleri olarak da tanımlayabilirsiniz (örneğin wp-config.php\'de). Bu kaynaklar, veritabanı anahtarı depolanmadığında otomatik olarak yedek olarak kullanılır.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Kullanıcı tarafından belirlenen şifreleme sırrını kullanmak için (türetilmiş wp_salt değili yerine), bunu wp-config.php\'ye ekleyin:','Unknown provider.'=>'Bilinmeyen sağlayıcı.','No API key configured for this provider.'=>'Bu sağlayıcı için yapılandırılmış API anahtarı yok.','Could not instantiate the provider.'=>'Sağlayıcı başlatılamadı.','Provider returned no response. Check the WordPress error log for details.'=>'Sağlayıcı yanıt vermedi. Detaylar için WordPress hata günlüğünü kontrol edin.','Enter a model identifier to test.'=>'Test etmek için bir model tanımlayıcısı girin.','No published post or page found to test with — publish some content first, or try Quick Translate directly.'=>'Test için yayınlanmış yazı veya sayfa bulunamadı — önce içerik yayınlayın veya doğrudan Hızlı Çeviri\'yi deneyin.','(untitled)'=>'(başlıksız)','Prompt template not found.'=>'İstem şablonu bulunamadı.','Translation failed. Please try again.'=>'Çeviri başarısız oldu. Lütfen tekrar deneyin.','The sample post has no visible text content to translate.'=>'Örnek yazının çevrilecek görünür metin içeriği yok.','Chunk prompt template not found.'=>'Parça istem şablonu bulunamadı.','Model returned no response. Check the WordPress error log for details.'=>'Model yanıt vermedi. Ayrıntılar için WordPress hata günlüğünü kontrol edin.','Behavior'=>'Davranış','Block Editor'=>'Blok Düzeni','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge, dil genelinde düzenleyici davranışı tutarlı tutmak için varsayılan olarak iki Gutenberg özelliğini sınırlar. Tam Gutenberg / FSE yeteneklerine ihtiyacınız olduğunda buradan katılın.','Block locking'=>'Blok kilitleme','Allow editors to lock individual blocks'=>'Editörlerin bireysel blokları kilitlemesine izin ver','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Gutenberg\'in canLockBlocks özelliğini yeniden etkinleştirir. Katkıda bulunanların belirli blokları taşımalarını veya silmelerini engellemesi gereken düzenleyici şablonlar için kullanışlıdır.','Template mode'=>'Şablon modu','Allow Gutenberg template-editing mode on post screens'=>'Yazı ekranlarında Gutenberg şablon düzenleme moduna izin ver','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'supportsTemplateMode\'u yeniden etkinleştirir. Yazı seviyesi şablon geçersiz kılmalarının kasıtlı olduğu Tam Site Düzenleme iş akışlarının temelidir.','Compliance Preset'=>'Uyumluluk Ön Ayarı','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Yasal, düzenleyici, tıbbi veya teknik içerik için katı koruma modu. Açık olduğunda, her yapay zeka özelliği düşük örnekleme sıcaklığı kullanır ve sistem istemine aşağıdaki ek açıklamayı ekler — terminoloji, makale numaraları, birimler, marka isimleri ve düzenleyici dil kelimesi kelimesine korunur, paraphrase edilmez.','Global AI preset'=>'Küresel Yapay Zeka ön ayarı','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, özellik başına','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Tüm site genelinde varsayılan yapay zeka davranışını ayarlar. Bireysel yazılar, Lingua Forge meta kutusu aracılığıyla Çeviri ve İçerik Oluşturma için bunu geçersiz kılabilir.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standart, her özelliğin kendi ayarlanmış sıcaklığını kullanır: Çeviri T=0.2 (kesin), Hızlı Çeviri T=0.4, İçerik Üretici T=0.6 (yaratıcı). Diğer ön ayarlar, tüm özelliklerde tek bir sabit sıcaklık uygular.','Technical / Scientific instructions'=>'Teknik / Bilimsel talimatlar','Legal / Compliance instructions'=>'Yasal / Uyumluluk talimatları','Creative / Marketing instructions'=>'Yaratıcı / Pazarlama talimatları','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Varsayılanı kullanmak için boş bırakın. Kaydedilen bir geçersiz kılmayı temizlemek, varsayılanı bir sonraki kayıtta geri yükler.','View built-in default'=>'Yerleşik varsayılanı görüntüle','Automatic Translation Backfill'=>'Otomatik Çeviri Geri Dolum','Periodically scans for posts missing a translation in an active language and queues an AI translation for each gap found — the same recovery you can already trigger by hand via "Translate missing" or the WP-CLI missing_translations/fill_translations commands, run automatically once an hour instead.'=>'Etkin bir dilde çeviri eksik olan yazıları periyodik olarak tarar ve bulunan her boşluk için AI çevirisi kuyruğa alır — "Eksik çevirileri çevir" aracılığıyla veya WP-CLI missing_translations/fill_translations komutlarıyla tetikleyebileceğiniz aynı kurtarma, bunun yerine saatte bir kez otomatik olarak çalışır.','Automatic backfill'=>'Otomatik geri dolum','Automatically translate posts missing a language version'=>'Dil sürümü eksik olan yazıları otomatik olarak çevirin','Off by default. This feature makes AI provider requests — and spends the associated API cost — automatically and in the background, with no per-request confirmation, for every published post found without a translation in an active language. Turn this on only if you want every content gap translated unattended; otherwise use "Translate missing" or the WP-CLI commands to translate on your own schedule.'=>'Varsayılan olarak kapalı. Bu özellik, AI sağlayıcı isteklerini yapar — ve ilişkili API maliyetini harcar — etkin bir dilde çevirisi olmayan her yayınlanmış yazı için otomatik olarak ve arka planda, istek başına onay olmaksızın. Bunu yalnızca her içerik boşluğunun katılımsız çevrilmesini istiyorsanız etkinleştirin; aksi takdirde "Eksik çevirileri çevir" veya WP-CLI komutlarını kendi zamanlamanıza göre kullanın.','WooCommerce products and variations are never included, regardless of this setting. An integration can also block specific post types via the linguaforge_cpt_create_allowed filter.'=>'WooCommerce ürünleri ve varyasyonları bu ayar ne olursa olsun asla dahil edilmez. Bir entegrasyon, linguaforge_cpt_create_allowed filtresi aracılığıyla belirli yazı türlerini de engelleyebilir.','The "Sync" button in the post list Lang column retranslates a post out into every other language, including the primary/source post when it\'s run from a translation. That back-translation direction is restricted by default for every post type. (WooCommerce products and variations have their own separate setting below — this one does not affect them.)'=>'Yazı listesindeki Lang sütunundaki "Senkronize Et" düğmesi, birincil/kaynak yazıdan çalıştırıldığında, bir yazıyı diğer tüm dillere yeniden çevirir ve birincil yazı da dahil olmak üzere. Bu ters çeviri yönü varsayılan olarak her yazı türü için sınırlıdır. (WooCommerce ürünleri ve varyasyonlarının aşağıda ayrı ayarları vardır — bu ayar onları etkilemez.)','Secondary-language Sync'=>'İkincil Dil Senkronizasyonu','Allow "Sync" on a translated post to overwrite the primary post'=>'Çevirili yazıda "Senkronize Et"in birincil yazının üzerine yazmasına izin verin','Off by default: clicking "Sync" on a translation is blocked from overwriting the primary post. Syncing FROM the primary post to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Varsayılan olarak kapalı: çeviriye tıklanan "Senkronize Et" birincil yazının üzerine yazılmaktan engellenir. Birincil yazıdan her çeviriye Senkronize Etme bu ayar ne olursa olsun her zaman izin verilir. Bunu yalnızca bir çevirinin yeni kaynak içeriği olabilmesini istiyorsanız etkinleştirin.','The primary-language product is WooCommerce\'s operational source of truth for price, SKU, and stock, which are always served from it regardless of which language a shopper is viewing. This is a separate, independent setting from the general "Sync" restriction above — enabling one does not enable the other.'=>'Birincil dil ürünü, WooCommerce\'in fiyat, SKU ve stok için operasyonel gerçeğin kaynağıdır; alıcı hangi dili görüntülüyorsa bağlı olarak her zaman buradan sunulur. Bu, genel "Senkronize Et" kısıtlamasından ayrı, bağımsız bir ayardır — birini etkinleştirmek diğerini etkinleştirmez.','Allow "Sync" on a translated product to overwrite the primary product'=>'Çevirili üründe "Senkronize Et"in birincil ürünün üzerine yazmasına izin verin','Off by default: clicking "Sync" on a translated WooCommerce product is blocked, since it would back-translate onto the primary product\'s title, description, and excerpt. Syncing FROM the primary product to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Varsayılan olarak kapalı: çevirili WooCommerce ürününe tıklanan "Senkronize Et" engellenir, çünkü birincil ürünün başlığı, açıklaması ve alıntısının üzerine yazılır. Birincil üründen her çeviriye Senkronize Etme bu ayar ne olursa olsun her zaman izin verilir. Bunu yalnızca bir çevirinin yeni kaynak içeriği olabilmesini istiyorsanız etkinleştirin.','General'=>'Genel','Light'=>'Hafif','Meta Description, Excerpt Generator, quick translate'=>'Meta Açıklama, Alıntı Üreteci, hızlı çeviri','Quality'=>'Kalite','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'Tam sayfa Çeviri, İçerik Üreteci (orta seviye modeller tamamen yeterlidir)','Active Provider'=>'Aktif Sağlayıcı','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Şu anda %s sabitinden miras alınmıştır. Buraya bir değer seçmek, onu geçersiz kılar.','WordPress AI Client — requirements:'=>'WordPress AI İstemcisi — gereksinimler:','Full-page translation uses JSON-schema-constrained output. This requires a connector plugin to be installed and active (not just an API key saved in Settings → Connectors). If translation fails, check the PHP error log for the specific error, or switch to a built-in provider.'=>'Tam sayfa çeviri, JSON şema kısıtlamalı çıktı kullanır. Bu, bir bağlayıcı eklentisinin kurulup etkinleştirilmesini gerektirir (Ayarlar → Bağlayıcılar\'da saklanan bir API anahtarı yeterli değildir). Çeviri başarısız olursa, belirli hatayı görmek için PHP hata günlüğünü kontrol edin veya yerleşik bir sağlayıcıya geçin.','Manage your account, review usage, or top up credits:'=>'Hesabınızı yönetin, kullanımınızı gözden geçirin veya kredilerinizi yükleyin:','WordPress Connectors'=>'WordPress Bağlayıcıları','Models'=>'Modeller','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Özellikler iki seviyeye ayrılmıştır. Her seviye ve sağlayıcı için tam model tanımlayıcısını girin. Yer tutucu olarak gösterilen yerleri boş bırakın. Yalnızca aktif sağlayıcının modelleri çalışma zamanında çağrılır — diğerlerini önceden yapılandırın, eğer değiştirmeyi planlıyorsanız.','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'Herhangi bir alana yazmaya başlayın veya aşağıdaki referans tablosunu kullanın. Hafif ve orta seviye Kalite modelleri (Haiku, GPT-4o mini, Gemini Flash) çeviri ve içerik üretimi için tamamen yeterlidir — amiral gemisi "max" modeller maliyeti artırır, yapısal metin için kalite artışı minimaldir.','active'=>'aktif','Model selection is managed by WordPress in %s — no model identifier is stored by Lingua Forge for this provider.'=>'Model seçimi, %s\'de WordPress tarafından yönetilir — bu sağlayıcı için Lingua Forge tarafından herhangi bir model tanımlayıcısı saklanmaz.','overridden'=>'geçersiz kılındı','Translates a short sample of your most recent published post with this exact model — a real, billed API call.'=>'En son yayınlanmış yazınızdan kısa bir örneği bu tam modelle çevirin — gerçek, faturalandırılan bir API çağrısı.','Test model'=>'Test modelini dene','Tip: to reset a model to the built-in default, clear the field and save.'=>'İpucu: Bir modeli yerleşik varsayına sıfırlamak için alanı temizleyin ve kaydedin.','Available models reference'=>'Mevcut modeller referansı','Model ID'=>'Model Kimliği','Name'=>'İsim','Tier'=>'Seviye','Notes'=>'Notlar','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'Bu katalog, her Lingua Forge sürümünde güncellenir. API Anahtarları sekmesinde bir bağlantı testi yapmak, sağlayıcıdan canlı model listesini de getirir ve yukarıdaki önerileri yeniler.','Glossary'=>'Terim Sözlüğü','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Dil çifti başına kullanıcı tarafından yönetilen terim tablosu. Girişler, AI\'nın tercih edilen terimleri tutarlı şekilde kullanması için çeviri sisteminin istemine eklenir — alan kelime dağarcığı ("kWp", "PPA", "bağlantı noktası"), değiştirilmemesi gereken marka isimleri ve standartlaştırılmış düzenleyici ifadeler için kritik önemdedir. Her iki dil alanı da isteğe bağlıdır: "Kaynak dili" boş bırakın, böylece giriş hangi dilden çeviri yapılıyor olursa olsun uygulanır; "Hedef dili" boş bırakın, böylece tüm hedef dillere aynı anda uygulanır.','Glossary entry added.'=>'Terimlik girişi eklendi.','Glossary entry removed.'=>'Terimlik girişi kaldırıldı.','Could not add entry: source term and target term are required.'=>'Giriş eklenemedi: kaynak terim ve hedef terim gereklidir.','Could not save the glossary entry.'=>'Terimlik giriş kaydedilemedi.','Source language'=>'Kaynak dili','— Any —'=>'— Herhangi —','Target language'=>'Hedef dil','— Any target —'=>'— Herhangi hedef —','Filter'=>'Filtre','Reset'=>'Sıfırla','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Mevcut filtreyle eşleşen terimlik girişi yok. Tüm girişleri görmek için filtreyi temizleyin veya aşağıda yeni bir giriş ekleyin.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Henüz terimlik girişi yok. Çevirilerde terimlerin uygulanmaya başlaması için aşağıda bir tane ekleyin.','Source term'=>'Kaynak terim','Target term'=>'Hedef terim','Source lang'=>'Kaynak dil','Target lang'=>'Hedef dil','any'=>'herhangi','Delete this glossary entry?'=>'Bu terimlik giriş silinsin mi?','Add new entry'=>'Yeni giriş ekle','The phrase as it appears in the source text.'=>'Kaynak metinde göründüğü şekliyle ifade.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Çeviride nasıl görünmesi gerektiği. Aynı değeri kaynak terimle girin, böylece AI\'nin aynen korumasını sağlayın.','— Any source language —'=>'— Herhangi kaynak dili —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Marka isimleri ve dilden bağımsız terimler için boş bırakın, bunlar hangi dilden çeviri yapılıyor olursa olsun zorunludur.','— Any target language —'=>'— Herhangi hedef dili —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Bu girdiyi tüm hedef dillere uygulamak için boş bırakın — marka isimleri, kısaltmalar ve her çeviride aynen korunması gereken terimler için idealdir.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Editörler için isteğe bağlı bağlam (ör. "ASIC = Uygulamaya Özgü Entegre Devre; teknik bağlamlarda İngilizce korunmalı").','Add entry'=>'Giriş ekle','Limits'=>'Sınırlar','Authors and above (edit_published_posts)'=>'Yazarlar ve üzeri (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Katkıda bulunanlar ve üzeri — varsayılan (edit_posts)','Editors and above (edit_others_posts)'=>'Editörler ve üzeri (edit_others_posts)','Administrators only (manage_options)'=>'Yöneticiler sadece (manage_options)','AI Limits & Security'=>'AI Sınırları ve Güvenlik','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Site\'nin ne kadar AI kullanımı yapabileceğini sınırla ve hangi kullanıcı rollerinin ücretli AI çağrılarını tetikleyebileceğini kısıtla. Bu, zaten tek kullanıcı kaçak döngülerine karşı koruyan kullanıcı başına oran sınırının (30 istek / dakika, sabit kodlu) üzerine oturur.','Daily request limit'=>'Günlük istek sınırı','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'UTC günü başına site genelinde AI istekleri tavanı (Hem Araç Çubuğu çevirileri hem de blok revizyonlarını sayar). Sayacı UTC gece yarısı sıfırlar. Devre dışı bırakmak için 0 olarak ayarlayın.','Minimum role'=>'En düşük rol','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'AI özelliklerini tetiklemek için izin verilen en düşük WordPress yeteneği. Çok yazarlı sitelerde bunu sıkılaştırmak, Katkıda Bulunanlar veya deneme hesaplarının ücretli AI çağrılarını çalıştırmasını engeller. Özellik başına override etmek için linguaforge_required_capability filtresini kullanın.','Translation Limits'=>'Çeviri Sınırları','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'AI\'ye gönderilen içerik miktarını ve yanıtın ne kadar büyük olabileceğini kontrol et. Bir alanı boş bırakmak yerleşik varsayılanı kullanır (yer tutucu olarak gösterilir). Büyük sayfalar kesiliyorsa bu değerleri artırın; API maliyetlerini azaltmak için düşürün.','Model tier'=>'Model seviyesi','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Kalite (varsayılan — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Hafif (hızlı ve maliyet etkin — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Tam sayfa çeviri için kullanılacak model seviyesi. Kalite, yukarıdaki Modeller tablosunda yapılandırılan modeli kullanır ve doğru, uzun biçimli çeviri için önerilir. Sadece hız veya maliyet öncelikliyse ve içerik kısa ise Hafif\'e geçin.','Max output tokens'=>'Maksimum çıktı token sayısı','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'AI\'nin tek bir çeviri yanıtında üretebileceği maksimum token sayısı. Bir çeviri sessizce kesilirse, bu değeri artırın. Varsayılan: 16.000.','Max input characters'=>'Maksimum giriş karakterleri','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'AI\'ye iletilen gönderi içeriğinin maksimum karakter sayısı. 0 ise sınır yok — tam içerik her zaman gönderilir (önerilir). Sağlayıcınızın sıkı bir bağlam penceresi varsa, sıfır olmayan bir değer ayarlayın. İçerik kısaltıldığında PHP hata günlüğüne uyarı yazılır.','Quick Translation'=>'Hızlı Çeviri','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Hızlı Çeviri, snippet/parça modu için kullanılır — araç çubuğu, düzenleyici veya blok açılır pencerelerinden talep üzerine kısa pasajlar çevrilir. Yanıtları hızlı ve maliyet etkin tutmak için tam sayfa çeviriden ayrı, daha hafif bir yapılandırma kullanır.','Light (default — fast and cost-effective)'=>'Hafif (varsayılan — hızlı ve maliyet etkin)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Kalite (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Hafif katman, yukarıdaki Modeller tablosunda yapılandırılmış hızlı modeli kullanır (varsayılan: Haiku / Flash). Parçalar için tam sayfa modu kadar çeviri doğruluğu gerekiyorsa Kalite\'ye geçin.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'AI\'nin her hızlı çeviri için üretebileceği maksimum token sayısı. Varsayılan: 2.000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Giriş alanından kabul edilen maksimum karakter sayısı. Varsayılan: 8.000.','Content Generator'=>'İçerik Üreteci','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'AI İçerik Üreteci özelliği için token bütçesi ve giriş limitlerini kontrol eder. Alanları boş bırakmak, yerleşik varsayılanları kullanır.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Her üretim çalışması için AI\'nin üretebileceği maksimum token sayısı. Tam makaleler kesiliyorsa artırın. Varsayılan: 8.192.','Max hints characters'=>'İpucu karakterleri için maksimum sınır','Maximum characters read from the Hints field. Default: 2 000.'=>'İpucu alanından okunan maksimum karakter sayısı. Varsayılan: 2.000.','Max context characters'=>'Maksimum bağlam karakterleri','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'İpucu sağlanmadığında, AI\'ye iletilen mevcut gönderi içeriğinin maksimum karakter sayısı. Varsayılan: 6.000.','Maintenance'=>'Bakım','Router'=>'Yönlendirici','Primary language saved.'=>'Birincil dil kaydedildi.','Permalink rules flushed successfully.'=>'Kalıcı bağlantı kuralları başarıyla temizlendi.','Language uninstalled. %d post deleted.'=>'Dil kaldırıldı. %d gönderi silindi.' . "\0" . 'Dil kaldırıldı. %d gönderi silindi.','%d locale file removed.'=>'%d yerel dosya kaldırıldı.' . "\0" . '%d yerel dosya kaldırıldı.','%d pattern translation removed.'=>'%d desen çevirisi kaldırıldı.' . "\0" . '%d desen çevirisi kaldırıldı.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'%d yerel dosya otomatik olarak kaldırılamadı (DISALLOW_FILE_MODS ayarlandı). Bunu manuel olarak sunucunuz veya WP-CLI aracılığıyla silin: wp language core uninstall <locale>' . "\0" . '%d yerel dosya kaldırılamadı (DISALLOW_FILE_MODS ayarlandı). Bunu manuel olarak sunucunuz veya WP-CLI aracılığıyla silin: wp language core uninstall <locale>','Primary Language'=>'Birincil Dil','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Birincil dil, sitenizin kökünde her zaman sunulur — yol modunda URL öneki yok, alt alan adında dil alt alan adı yok. Diğer tüm diller, aşağıdaki URL yapı ayarına bağlı olarak ya /lang/ yol öneki (ör. example.com/de/) ya da dil alt alan adı (ör. de.example.com) kullanır.','Primary language'=>'Birincil dil','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Birincil dili değiştirdikten sonra, URL yönlendirmesinin güncellenmesi için kalıcı bağlantıları (aşağıdaki bölüm) temizleyin.','Path prefix — example.com/de/'=>'Yol öneki — example.com/tr/','Subdomain — de.example.com/'=>'Alt alan adı — tr.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Alt alan adı modu, web sunucunuzun tüm dil alt alan adlarını (ör. tr.example.com) bu WordPress kurulumuna yönlendirmesini gerektirir. Modları değiştirdikten sonra kalıcı bağlantı kurallarını temizleyin ve önbellekleri boşaltın. Ana URL\'nizde www varsa (ör. www.example.com), alt alan adlarının doğru şekilde oluşturulması için lf_base_domain filtresini kullanarak çıplak kök alan adını ayarlayın.','Browser language redirect'=>'Tarayıcı dili yönlendirmesi','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Ziyaretçileri, tarayıcının Accept-Language başlığına göre tercih ettikleri dile yönlendirin','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Etkinleştirildiğinde, ilk kez gelen ve dil çerezi veya URL\'de dil öneki olmayan ziyaretçiler, en yakın eşleşen dil sürümüne yönlendirilir. Yönlendirme, tarayıcının tercih ettiği dil aktif yönlendirici diller arasında değilse atlanır. Bir ziyaretçi, dil değiştirme aracını kullanarak bir dil seçtikten sonra, çerez öncelik kazanır ve tarayıcı başlığı tüm gelecekteki ziyaretlerde göz ardı edilir.','Query Filter Exclusions'=>'Sorgu Filtreleri Hariç Tutmaları','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Lingua Forge, aktif dilye _lf_lang meta kısıtlaması ekleyerek ikincil WP_Query örneklerini (yan menü widget\'ları, şablon blokları, eklenti aramaları) sınırlar. Burada listelenen gönderi türleri bu kısıtlamadan hariç tutulur — sorguları her zaman filtrelenmemiştir.','Contact Form 7 (wpcf7_contact_form), Flamingo contacts and inbound messages (flamingo_contact, flamingo_inbound), and WordPress language-pack sync storage (wp_sync_storage) are excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'İletişim Formu 7 (wpcf7_contact_form), Flamingo iletişimleri ve gelen mesajlar (flamingo_contact, flamingo_inbound), ve WordPress dil paketi senkronizasyon depolama alanı (wp_sync_storage) otomatik olarak hariç tutulur. İçeriği dil filtresine takılmaması gereken diğer üçüncü taraf gönderi türlerini, satır başı veya virgülle ayrılmış olarak ekleyin.','Excluded post types'=>'Hariç tutulan gönderi türleri','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'Virgül veya yeni satırla ayrılmış gönderi tipi takma adları. Değişiklikler kaydedildiğinde hemen etkili olur — kalıcı bağlantı temizlemesine gerek yok.','WooCommerce Integration'=>'WooCommerce Entegrasyonu','Controls how Lingua Forge integrates with WooCommerce order processing.'=>'Lingua Forge\'un WooCommerce sipariş işlemleriyle entegrasyonunu kontrol eder.','Order line item source mapping'=>'Sipariş satır öğesi kaynak eşlemesi','Normalize order line item product IDs to the source-language product at checkout'=>'Ödeme sırasında kaynak dil ürününe normalize et order satır öğesi ürün kimlikleri','When enabled (recommended), the product ID stored on each WooCommerce order line item is set to the source-language product. This ensures total_sales counts, WC Analytics revenue rows, and third-party ERP exports reference one product ID per SKU rather than one per language version. Trade-off: "View product" links in order emails and My Account lead to the source-language page. Disable only if a connected system relies on translated product IDs in orders. Use the linguaforge_wc_order_item_source_mapping filter for per-item overrides.'=>'Etkinleştirildiğinde (önerilir), her WooCommerce sipariş satırında saklanan ürün kimliği kaynak dil ürününe ayarlanır. Bu, toplam satış sayımlarını, WC Analitik gelir satırlarını ve üçüncü taraf ERP ihracatlarını, her SKU için bir ürün kimliği yerine dil sürümüne göre referans verir. Tavsiye: "Ürünü görüntüle" bağlantıları sipariş e-postalarında ve Hesabım\'da kaynak dil sayfasına gider. Sadece bağlı bir sistem, siparişlerde çevrilmiş ürün kimliklerine dayanıyorsa devre dışı bırakın. Her öğe için geçersiz kılmak üzere linguaforge_wc_order_item_source_mapping filtresini kullanın.','Save Router Settings'=>'Yönlendirici Ayarlarını Kaydet','Flush Permalinks'=>'Kalıcı Bağlantıları Temizle','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'WordPress yeniden yazma kurallarını yeniden oluşturur, böylece URL önekleri, dil özelindeki takma adlar ve arşiv yeniden yazmaları senkronize olur. Birincil dil değiştirildikten veya yeni dil desteği eklendikten sonra gereklidir.','Flush Permalink Rules'=>'Kalıcı Bağlantı Kurallarını Temizle','Active Languages'=>'Aktif Diller','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Yönlendirici tarafından şu anda bilinen diller (kurulu WordPress yerel paketleri ve birincil dilden türetilmiştir). Yönlendirme ve çeviri için daha fazla dil kullanılabilir hale getirmek üzere aşağıdaki bölümde ek dil paketleri yükleyin.','%d locale pack installed.'=>'%d yerel paket yüklü.' . "\0" . '%d yerel paket yüklü.','Install a Language'=>'Bir Dil Yükle','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'WordPress.org\'dan doğrudan bir WordPress çekirdek dil paketi indirip yükleyin. Yüklendikten sonra, yerel ayar URL yönlendirmesi ve AI çeviri akışı için kullanılabilir hale gelir. Mevcut diller listesi talep üzerine alınır — aşağıdaki düğmeye tıklayarak yükleyin.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Bu sunucuda dil yükleme devre dışı bırakılmıştır. wp-config.php dosyasında DISALLOW_FILE_MODS sabiti ayarlanmıştır. Dil paketlerini manuel olarak WP-CLI ile yükleyin: wp language core install de_DE','Load available languages'=>'Mevcut dilleri yükle','— select a language —'=>'— bir dil seçin —','Install'=>'Yükle','Language Setup'=>'Dil Kurulumu','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'İkincil dil yapılandırılmamış. Şablon iskeletini etkinleştirmek için yukarıdaki dil paketini yükleyin.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Bir dil seçin ve onun FSE şablonlarını, şablon parçalarını ve gezinme menülerini yönetin.','Recreate All Languages'=>'Tüm Dilleri Yeniden Oluştur','Recreate All Languages (Templates Only)'=>'Tüm Dilleri Yeniden Oluştur (Yalnızca Şablonlar)','Recreate All Languages (Template Parts Only)'=>'Tüm Dilleri Yeniden Oluştur (Yalnızca Şablon Parçaları)','Cancel'=>'İptal','Repair Template Metadata'=>'Şablon Meta Verisini Onar','Fixes the Site Editor namespace and _lf_lang tag on all LF-scaffolded FSE templates stored in the database. Run this once after updating from an earlier version of Lingua Forge — it moves WooCommerce-derived templates from the active-theme group to the WooCommerce group in the Site Editor, and ensures all scaffolded templates are discoverable by coverage reports.'=>'Site Editör isim alanını ve _lf_lang etiketini veritabanında saklanan tüm LF-çerçeveli FSE şablonlarında düzeltir. Bu, Lingua Forge\'un önceki sürümünden güncelledikten sonra bir kez çalıştırın — WooCommerce türetilmiş şablonları aktif tema grubundan WooCommerce grubuna taşır ve tüm çerçevelenmiş şablonların kapsama raporları tarafından bulunmasını sağlar.','Repair template metadata'=>'Şablon meta verisini onar','Request failed.'=>'İstek başarısız oldu.','Forbidden'=>'Yasaklandı','Danger Zone'=>'Tehlike Bölgesi','Uninstall %s'=>'Kaldır %s','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Bu dil ile ilişkili tüm şablonları, şablon parçalarını, desenleri, gezinme menülerini, gönderileri, sayfaları, özel gönderi türlerini, ürünleri ve ürün varyasyonlarını kalıcı olarak siler. Ayrıca, bu dilin artık yönlendiricide görünmesini engellemek için WordPress yerel paket dosyalarını da kaldırır. Bu işlem geri alınamaz.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Bu dil, WordPress örneği yerel ayarına uyar ve kaldırılamaz.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'%s kalıcı olarak kaldırılır mı? Bu, bu dil için tüm çevrilmiş içeriği siler ve geri alınamaz.','Invalid language code.'=>'Geçersiz dil kodu.','This language is protected and cannot be uninstalled.'=>'Bu dil korumalıdır ve kaldırılamaz.','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Bu sunucuda dil yükleme devre dışı bırakılmıştır (DISALLOW_FILE_MODS ayarlanmış).','Invalid locale code.'=>'Geçersiz yerel kod.','Language %s installed successfully.'=>'Dil %s başarıyla yüklendi.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Dil paketi yüklemesi başarısız oldu. Dil zaten yüklü olabilir, yerel kod yanlış olabilir veya sunucunuz dosya yazma işlemlerini engelliyor olabilir.','Navigations'=>'Gezintiler','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Gezinti çevirisi, aktif bir AI sağlayıcısı gerektirir. API Anahtarları sekmesinde bir API anahtarı yapılandırın.','Navigation'=>'Gezinti','Re-translate'=>'Yeniden çevir','CPT Block Patterns'=>'CPT Blok Desenleri','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Özel gönderi türleri için kaydedilen blok desenleri. Bir dil varyantı üretmek için Çevir düğmesini kullanın. Çevirilen içerik burada kaydedilir ve blok düzenleyici Desen ekleyicisinden herhangi bir CPT gönderisine kopyalanabilir veya Senkronize Desen (Yeniden Kullanılabilir Blok) için başlangıç noktası olarak kullanılabilir.','Pattern'=>'Desen','Post Types'=>'Gönderi Türleri','✓ Translation saved'=>'✓ Çeviri kaydedildi','View'=>'Görüntüle','Template Parts'=>'Şablon Parçaları','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Temanın dil özelinde kopyaları. İskelet oluşturulduktan sonra, şablonlar dil özelinde parçayı referans gösterecek şekilde güncellenir.','Re-create all'=>'Tümünü yeniden oluştur','Translate all'=>'Tümünü çevir','Fix all links'=>'Tüm bağlantıları düzelt','Fix all navs'=>'Tüm navigasyonları düzelt','Part'=>'Parça','Status / Actions'=>'Durum / İşlemler','Create'=>'Oluştur','Templates'=>'Şablonlar','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Aktif temadan tohumlanan FSE şablonları. Site Düzenleyicisinde oluşturun ve özelleştirin.','Create missing'=>'Eksik olanı oluştur','Fix all parts'=>'Tüm parçaları düzelt','SEO'=>'SEO','Multilingual SEO'=>'Çok dilli SEO','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'Her dil için hreflang, Open Graph, Schema.org, site haritaları ve sosyal paylaşım ayarlarını yapılandırın. Aşağıdaki her bölüm çok dilli SEO\'nun bir yönünü ele alır.','Open Graph &amp; Twitter Cards'=>'Open Graph &amp; Twitter Kartları','Schema.org'=>'Schema.org','Sitemap'=>'Site Haritası','Analysis'=>'Analiz','Compatibility'=>'Uyumluluk','System'=>'Sistem','Overview'=>'Genel Bakış','Lingua Forge Settings'=>'Lingua Forge Ayarları','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge, çok dilli yönlendirme, AI destekli çeviri, hreflang SEO etiketleri ve dil değiştirme aracını WordPress sitenize ekler.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Her alanı yapılandırmak için bu sayfanın üstündeki sekmeleri kullanın. Router sekmesindeki değişiklikler hemen etkili olur; AI anahtarları ve model ayarlarına yapılan değişiklikler bir sonraki AI isteğine uygulanır.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'URL yapılandırma ayarlarını değiştirdikten sonra (yol öneki ↔ alt alan adı), her zaman Ayarlar → Kalıcı Bağlantılar bölümüne gidin ve Yeniden Yazma Kurallarını Temizle\'ye tıklayın.','AI Provider Tab'=>'Yapay Zeka Sağlayıcı Sekmesi','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Select the active provider from the dropdown — only one provider is used at a time. Enter an API key for that provider to enable AI features.'=>'Desteklenen sağlayıcılar: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Açılır listeden aktif sağlayıcıyı seçin — yalnızca bir sağlayıcı kullanılır. Bu sağlayıcı için bir API anahtarı girin ve yapay zeka özelliklerini etkinleştirin.','Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Anahtarlar, siteye özgü bir gizli anahtar (LINGUAFORGE_SECRET) ile AES-256-GCM kullanılarak dinlenirken şifrelenir. Anahtarı değiştirmeden veritabanı dışa aktarımını paylaşmayın.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'AI özellikleri isteğe bağlıdır. Dil yönlendirme, hreflang, dil değiştirme ve çeviri grup sistemi, bir sağlayıcı yapılandırılmadan çalışır.','Model tiers'=>'Model katmanları','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge, sağlayıcı başına iki model katmanı kullanır:','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Hafif: meta açıklamaları ve özet oluşturma için kullanılır — hızlı, düşük maliyetli.','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Kalite: gönderi çevirisi ve içerik oluşturma için kullanılır — daha yüksek kalite, daha yüksek maliyet.','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Bir model alanını boş bırakın, bu katman için yerleşik varsayılanı kullanın. Yer tutucu metin, hangi modelin kullanılacağını gösterir.','Translation Limits & Behavior'=>'Çeviri Sınırları ve Davranışları','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Çeviri Sınırları: hangi kullanıcı rollerinin AI çevirisini tetikleyebileceğini kontrol edin ve aylık token bütçesi belirleyin. Bütçeyi aşmak, ay reset olana kadar AI çağrılarını askıya alır.','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Davranış: AI ön ayarını seçin (Literal, Balanced, Creative), site genelinde özel istem prompt talimatları ekleyin, otomatik gönderi kaydetme çevirisini etkinleştirin veya devre dışı bırakın ve Çeviri Belleği\'ni yapılandırın.','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Çeviri Belleği, içerik karma, dil çifti, sağlayıcı ve model bazında AI sonuçlarını önbelleğe alır. Bir gönderiyi düzenlemek, önbellek girişini geçersiz kılar, böylece bir sonraki çeviri çağrısı taze bir sonuç alır.','Router Tab'=>'Yönlendirici Sekmesi','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Birincil dil: mevcut içeriğinizin yazıldığı dil. Tüm çeviriler bu dilden üretilir; değiştirmek, gönderileri taşımak veya silmek anlamına gelmez.','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL yapısı: yol öneki modu (example.com/de/) sunucu değişikliği gerektirmez. Alt alan adı modu (de.example.com) ise joker DNS kaydı, joker SSL sertifikası ve web sunucusu yapılandırması değişikliği gerektirir — Sunucu Kurulumu kılavuzuna bakın.','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Aktif diller: desteklemek istediğiniz her dili ekleyin. Her dil, bir URL öneki veya alt alan adı ve sayfa &lt;head&gt; bölümünde bir hreflang etiketi alır.','WP site language requirement'=>'WP site dil gereksinimi','The WordPress site language (Settings → General → Site Language) must be set to one of the languages you use for content — either the primary content language or one of the secondary languages. It cannot be a language that has no content on the site.'=>'WordPress sitesi dili (Ayarlar → Genel → Site Dili) içerik için kullandığınız dillerden biri olmalıdır — ya ana içerik dili ya da ikincil dillerden biri. Site üzerinde içerik olmayan bir dil olamaz.','Example of a supported configuration: WP site language = CA (Catalan), content languages = CA + ES.'=>'Desteklenen yapılandırma örneği: WP site dili = Katalanca (CA), içerik dilleri = CA + ES.','Example of an unsupported configuration: WP site language = EN (English), content languages = CA + ES only. English is not a content language, so Lingua Forge cannot map the WP locale to any translation group.'=>'Desteklenmeyen yapılandırma örneği: WP site dili = İngilizce (EN), içerik dilleri = sadece CA + ES. İngilizce içerik dili değildir, bu yüzden Lingua Forge WP yerel ayarını herhangi bir çeviri grubuna eşleyemez.','When the WP site language is not a content language: WooCommerce product queries return zero results on all catalogue blocks; product image delegation fails; all language-filtered content queries break; the language switcher may show a spurious non-content language option. If you see a red configuration alert at the top of the Router or System tab, correct the site language first.'=>'WP site dili içerik dili değilse: WooCommerce ürün sorguları tüm katalog bloklarında sıfır sonuç döner; ürün resmi delegasyonu başarısız olur; tüm dil filtreli içerik sorguları bozulur; dil değiştirme arayüzü sahte olmayan içerik olmayan bir dil seçeneği gösterebilir. Router veya Sistem sekmesinin üstünde kırmızı bir yapılandırma uyarısı görüyorsanız, önce site dilini düzeltin.','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE yerelleştirme: bu sekmeden doğrudan Tam Site Düzenleme şablonları ve şablon parçalarında iskelet, çeviri ve bağlantıları düzeltin.','Glossary Tab'=>'Sözlük Sekmesi','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Çevirilmemesi veya belirli bir şekilde gösterilmesi gereken terimleri sabitleyin (örneğin marka isimleri, ürün isimleri, kısaltmalar). Sözlük kısıtlamaları, tüm özellikler için AI çevirisi talebine enjekte edilir: gönderi çevirisi, meta açıklaması, özet ve FSE şablon çevirisi.','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Bir satıra bir terim ekleyin. Hem kaynak terim hem de hedef gösterim gereklidir. Dil çifti, hangi çeviri işleri için kısıtlamanın geçerli olduğunu belirler.','SEO Tab'=>'SEO Sekmesi','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge, eksiksiz çok dilli SEO çözümüdür. Ek bir SEO veya site haritası eklentisi gerekmez.','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Sağladıklarımız: her yapılandırılmış dil için hreflang etiketleri, og:locale ve og:locale:alternate ile Open Graph ve Twitter Kart etiketleri, Schema.org JSON-LD ile inLanguage açıklamaları ve tüm çeviri grupları için xhtml:link alternatif girişleriyle /lf-sitemap.xml adresinde özel çokdillili site haritası.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'Site haritası otomatik olarak robots.txt\'de duyurulur. Tüm büyük arama motorları — Google, Bing, Yandex — bunu robots.txt\'den keşfeder. Manuel gönderim gerekmez.','SEO plugins and conflict avoidance:'=>'SEO eklentileri ve çakışma önleme:','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Yoast SEO, Rank Math, All in One SEO veya SEOPress yüklü ise, Lingua Forge bunları tespit eder ve çakışmayı önlemek için uyum sağlar. hreflang için, LF tamamen devralır ve bu eklentilerin çok dilli yönlendirme yapılandırması için doğru hreflang üretememeleri nedeniyle çıktılarını engeller. Open Graph için, LF yalnızca og:locale ve og:locale:alternate ekler — çok dilli sinyaller, eklentinin sağlayamayacağı — ve temel OG setini eklentiye bırakır. Schema.org için, LF kendi çıktısını tamamen devre dışı bırakır ve çakışan JSON-LD grafiklerini önler.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'SEO → Uyumluluk sekmesi canlı tespit durumunu gösterir ve LF\'nin her özellik alanında yaptığı işlemleri açıklar.','SEO Scores'=>'SEO Puanları','SEO Score System'=>'SEO Puan Sistemi','Score computation'=>'Puan hesaplama','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'Her gönderi, başlık, meta açıklama, kelime sayısı, başlık yapısı, görsel alternatif metin kapsamı ve dahili bağlantılar olmak üzere altı kural tabanlı metrikten 0-100 arasında puan alır. Okuma süresi her zaman on puan ile ödüllendirilir (bilgilendirici amaçlı). Kalan 90 puan, içerik profiline göre değişen ağırlıklarla diğer metrikler arasında dağıtılır (aşağıya bakın).','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'Her metrik dört durumdan birini verir: tamam (tam ağırlık), uyarı (ağırlığın %50\'si), başarısız (0) veya bilgi (0, ceza yok). 80 ve üzeri puan yeşil, 50–79 turuncu, 50\'nin altında kırmızı.','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'Başlık puanlama kuralları (tüm profiller): boşsa başarısız; 10 karakterden azsa uyarı; sadece bir kelime ise uyarı; profilin SERP sınırını aşarsa (Blog için 60 karakter, Ürün/Landing için 70); en az 10 karakter, en az 2 kelime ve SERP sınırında ise tamamdır.','Content profiles and weights'=>'İçerik profilleri ve ağırlıklar','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'Profiller, analiz edilen içerik türüne göre eşik ve ağırlıkları uyarlıyor. Profil otomatik olarak çözülür; profil açılır menüsünden her analiz çalıştırmasında üzerine yazabilirsiniz.','Blog / Editorial (default)'=>'Blog / Editoryal (varsayılan)','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'Başlık 15 puan · Meta açıklama 20 puan · Kelime sayısı 15 puan · Başlıklar 20 puan · Görseller 10 puan · Bağlantılar 10 puan. Başlık SERP sınırı 60 karakter; meta 120–210 karakter; kelime sayısı 300\'ün altında uyarır, 100\'ün altında başarısız olur; H2 zorunludur; dahili bağlantılar zorunludur.','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'WooCommerce ürünleri için otomatik algılandı. Başlık 20 puan · Meta açıklama 30 puan · Kelime sayısı 15 puan · Başlıklar 5 puan · Görseller 20 puan · Bağlantılar 0 puan. Başlık SERP sınırı 70 karakter; kelime sayısı 80\'nin altında uyarı, 40\'ın altında başarısız; H2 ve dahili bağlantılar isteğe bağlıdır.','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'Statik ana sayfa için otomatik algılandı; manuel olarak seçilebilir. Başlık 20 puan · Meta açıklama 30 puan · Kelime sayısı 15 puan · Başlıklar 10 puan · Görseller 15 puan · Bağlantılar 0 puan. Başlık SERP sınırı 70 karakter; kelime sayısı 150\'nin altında uyarı, 60\'ın altında başarısız; H2 ve dahili bağlantılar isteğe bağlıdır.','Heading structure rules'=>'Başlık yapısı kuralları','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'Tam olarak bir H1 gereklidir. H1 genellikle temanın render ettiği gönderi başlığıdır — mümkünse canlı render edilen sayfadan okunur ve yedek olarak gönderi içeriğinden alınır.','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'Blog profili H2 gerektiriyorsa ve bulunamazsa, analizör önce H3 alt başlıklarını kontrol eder ve uyarı verir. Accordion ve Details blokları başlıkları için varsayılan olarak H3 kullanır; bu H3\'ler geçerli yapı olarak kabul edilir ve iyi sonuç verir, uyarı vermez.','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'Kısa içerik (3 paragraf veya daha az) başlık eksikliği nedeniyle hiçbir zaman cezalandırılmaz, profil ne olursa olsun. Özlü bir sayfa zorunlu başlık yapısından fayda sağlamaz.','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'"H2\'yi H1 eşdeğeri olarak kabul et" (Ayarlar → SEO → Analiz): temanızın gönderi başlığını H1 yerine H2 içinde render ettiği durumlarda etkinleştirin. Analizör, ilk H2\'yi H1\'ye yükseltir, böylece puan yanlışlıkla cezalandırılmaz.','Score history and badges'=>'Puan geçmişi ve rozetler','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'Her gönderi analiz edildiğinde, puan gönderi meta verisine kaydedilir. Gönderi listesi Dil sütunu, en az bir kez analiz edilen herhangi bir gönderi için renk kodlu "SEO N" rozeti gösterir. İki skor kaydedildiğinde, önceki çalışmadan itibaren değişikliği gösteren bir delta göstergesi (↑N / ↓N) bulunur.','AI Usage & Cache Tab'=>'Yapay Zeka Kullanımı ve Önbellek Sekmesi','Token usage'=>'Jeton kullanımı','The usage table shows AI token consumption broken down by feature (translation, meta description, excerpt, FSE template, batch analysis), provider, and model. Use the date-range buttons to filter by today, last 7 days, last 30 days, or all time.'=>'Kullanım tablosu, yapay zeka token tüketimini özellik (çeviri, meta açıklama, alıntı, FSE şablonu, toplu analiz), sağlayıcı ve model bazında gösterir. Bugün, son 7 gün, son 30 gün veya tüm zaman dilimi için filtrelemek üzere tarih aralığı düğmelerini kullanın.','The daily quota (configured in Behavior → Limits) is tracked here. When the quota is reached, AI calls are suspended for the rest of the day. The table shows how much of the quota has been consumed.'=>'Günlük kota (Davranış → Limitlerde yapılandırılmış) burada izlenir. Kota dolduğunda, yapay zeka çağrıları gün sonuna kadar askıya alınır. Tablo, ne kadarının kullanıldığını gösterir.','Translation caching'=>'Çeviri önbellekleme','Lingua Forge uses two independent caching layers to reduce redundant AI API calls:'=>'Lingua Forge, gereksiz yapay zeka API çağrılarını azaltmak için iki bağımsız önbellek katmanı kullanır:','Stores raw AI responses keyed by content hash, language pair, provider, model, and preset. Cache entries are invalidated automatically when the source post content changes. Clear individual post entries or the whole cache from this tab.'=>'İçerik öbeği, dil çifti, sağlayıcı, model ve ön ayar anahtarlarıyla şifrelenmiş ham yapay zeka yanıtlarını saklar. Kaynak gönderi içeriği değiştiğinde önbellek girişleri otomatik olarak geçersiz kılınır. Bu sekmeden bireysel gönderi girişlerini veya tüm önbelleği temizleyin.','Stores the full translated post output per content hash. Opt-in (enabled in Behavior). Speeds up repeated translations of unchanged content. Clear it here when you want to force a fresh AI pass regardless of whether the content has changed.'=>'İçerik öbeği başına tam çevrilmiş gönderi çıktısını saklar. Katılma (Davranışta etkinleştirilmiş). Değişmeyen içeriğin tekrar çevirisini hızlandırır. İçeriğin değişip değişmediğine bakılmaksızın yeni bir yapay zeka geçişi yapmak istediğinizde buradan temizleyin.','Maintenance Tab'=>'Bakım Sekmesi','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Dil Üzerinden Geçersizlikler: Lingua Forge UI dizeleri için özel .po/.mo geçersizlik dosyalarını yönetin. Bu, eklenti dosyalarını doğrudan düzenlemek yerine kullanılır — geçersizlikler güncellemelerden sonra da kalır.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Hata ayıklama: AI istemlerini ve API yanıtlarını yerel bir dosyaya yakalamak için hata ayıklama günlüğünü etkinleştirin. Sorun giderme sonrası devre dışı bırakın — hata ayıklama modu her AI isteğinde bir dosya yazar.','Uninstall Behaviour: controls what is deleted when the plugin is removed from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments, translation relationships, meta descriptions, glossary, and Translation Memory are kept by default so an accidental uninstall or reinstall can pick up where it left off. Enable "Delete content data on uninstall" only when you are fully removing multilingual support from the site — this cannot be undone.'=>'Kaldırma Davranışı: Eklentiyi Eklentiler → Yüklü Eklentiler → Silme\'den kaldırırken neyin silineceğini kontrol eder. Eklenti ayarları ve Yapay Zeka önbellekleri her zaman kaldırılır. Dil atamaları, çeviri ilişkileri, meta açıklamalar, sözlük ve Çeviri Belleği varsayılan olarak korunur, böylece kazara kaldırma veya yeniden yükleme kaldığı yerden devam edebilir. "Kaldırırken içerik verilerini sil" seçeneğini yalnızca çok dilli desteği tamamen kaldırıyorsanız etkinleştirin — bu geri alınamaz.','System Tab'=>'Sistem Sekmesi','Read-only diagnostics for the current installation. No settings are changed here — use it to verify configuration, spot problems, and gather information for bug reports.'=>'Mevcut kurulum için salt okunur tanılama. Burada ayar değiştirilmez — yapılandırmayı doğrulamak, sorunları tespit etmek ve hata raporları için bilgi toplamak amacıyla kullanılır.','Sections'=>'Bölümler','Lingua Forge, WordPress, and PHP versions; active theme; URL structure; WP site language and primary content language. A red indicator next to the WP site language means it is not one of the active content languages — fix it in Settings → General before anything else.'=>'Lingua Forge, WordPress ve PHP sürümleri; aktif tema; URL yapısı; WP site dili ve ana içerik dili. WP site dilinin yanındaki kırmızı gösterge, bunun aktif içerik dillerinden biri olmadığını gösterir — önce Ayarlar → Genel\'de düzeltin.','Active provider, configured keys, model tier selections, preset, and daily quota.'=>'Aktif sağlayıcı, yapılandırılmış anahtarlar, model katmanı seçimleri, ön ayar ve günlük kota.','Confirms the permalink structure is compatible with Lingua Forge path routing. Plain and numeric-only structures are not supported.'=>'Permalink yapısının Lingua Forge yol yönlendirmesiyle uyumlu olduğunu doğrular. Düz ve sayısal yapılar desteklenmiyor.','Lists any active third-party SEO plugins. Lingua Forge adapts its output when these are present — see Settings → SEO → Compatibility for the per-feature breakdown.'=>'Herhangi bir aktif üçüncü taraf SEO eklentisini listeler. Lingua Forge, bunlar mevcutken çıktılarını uyarlıyor — özellik başına detaylar için Ayarlar → SEO → Uyumluluk bölümüne bakın.','WooCommerce version, order storage mode (CPT / HPOS / shared), and a per-language translation coverage table for the four built-in WC pages (Shop, Cart, Checkout, My Account).'=>'WooCommerce sürümü, sipariş depolama modu (CPT / HPOS / paylaşılan) ve dört yerleşik WC sayfası (Mağaza, Sepet, Ödeme, Hesabım) için dil başına çeviri kapsama tablosu.','Lists post types that have published posts without a _lf_lang meta value. Posts missing this tag are invisible to all language filters. Use the Repair button to tag them with the source language, or Exclude to remove the post type from language routing entirely.'=>'Yayınlanmış gönderisi olan ve _lf_lang meta değeri olmayan gönderi türlerini listeler. Bu etiketi olmayan gönderiler tüm dil filtrelerine görünmez. Kaynak dili ile etiketlemek için Onar düğmesini kullanın veya dil yönlendirmesinden tamamen kaldırmak için Hariç tut\'u kullanın.','Collapsible dump of all LF-owned entries in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts after adding a new language.'=>'$wp_rewrite->extra_rules_top içindeki tüm LF\'ye ait girişlerin katlanabilir dökümü. Yeni bir dil ekledikten sonra 404 veya yönlendirme çatışmalarını teşhis etmek için kullanışlıdır.','One-click copy of a plain-text system summary covering all of the above sections. Paste this into a GitHub issue or support request so the full environment is visible at a glance.'=>'Yukarıdaki tüm bölümleri kapsayan düz metin sistem özeti tek tıklamayla kopyalanabilir. Bu, tüm ortamın tek bakışta görünmesi için GitHub sorununa veya destek talebine yapıştırın.','Found a bug or unexpected behaviour? Please open an issue on GitHub — include the Debug Info block above and a short description of what you expected vs. what happened.'=>'Bir hata veya beklenmedik davranış mı buldunuz? Lütfen GitHub\'da bir sorun açın — yukarıdaki Hata Ayıklama Bilgisi bloğunu ve ne beklediğiniz ile ne olduğu arasındaki kısa açıklamayı ekleyin.','Open an issue →'=>'Bir sorun açın →','Getting started'=>'Başlangıç','Server setup (subdomain)'=>'Sunucu kurulumu (alt alan adı)','Translation workflow'=>'Çeviri iş akışı','Language switcher'=>'Dil değiştirme aracı','WP-CLI reference'=>'WP-CLI referansı','Integration API'=>'Entegrasyon API\'si','Documentation'=>'Belgeler','Report an issue on GitHub'=>'GitHub\'da sorun bildir','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','WordPress AI Client (WP 7.0+)'=>'WordPress AI İstemcisi (WP 7.0+)','Meta Description, Excerpt Generator'=>'Meta Açıklaması, Alıntı Üretici','Translation, Content Generator'=>'Çeviri, İçerik Üretici','Testing…'=>'Test ediliyor…','✓ Connection OK'=>'✓ Bağlantı OK','✗ Failed:'=>'✗ Başarısız:','No response from provider — check the error log for details.'=>'Sağlayıcıdan yanıt alınamadı — detaylar için hata günlüğünü kontrol edin.','Network error — could not reach the WordPress AJAX endpoint.'=>'Ağ hatası — WordPress AJAX uç noktasına ulaşılamadı.','Translating a real post with this model…'=>'Bu modelle gerçek bir yazı çeviriliyor…','preset'=>'ön ayar','Loading…'=>'Yükleniyor…','Installing…'=>'Yükleniyor…','✓ Language installed.'=>'✓ Dil yüklendi.','✗ Error:'=>'✗ Hata:','Creating…'=>'Oluşturuluyor…','✓ All templates created.'=>'✓ Tüm şablonlar oluşturuldu.','Some templates could not be created.'=>'Bazı şablonlar oluşturulamadı.','Recreating…'=>'Yeniden oluşturuluyor…','✓ All templates recreated.'=>'✓ Tüm şablonlar yeniden oluşturuldu.','Some templates could not be recreated.'=>'Bazı şablonlar yeniden oluşturulamadı.','This overwrites this template with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Bu şablonu etkin temadan yeni bir kopyayla yazacak ve Site Editor özelleştirmelerini iptal edecek. Bu işlem geri alınamaz. Devam edilsin mi?','This overwrites every template with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Her şablonu etkin temadan yeni bir kopyayla yazacak ve Site Editor özelleştirmelerini iptal edecek. Bu işlem geri alınamaz. Devam edilsin mi?','✓ All parts recreated.'=>'✓ Tüm parçalar yeniden oluşturuldu.','Some parts could not be recreated.'=>'Bazı parçalar yeniden oluşturulamadı.','This overwrites this template part with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Bu şablon parçasını etkin temadan yeni bir kopyayla yazacak ve Site Editor özelleştirmelerini iptal edecek. Bu işlem geri alınamaz. Devam edilsin mi?','This overwrites every template part with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Her şablon parçasını etkin temadan yeni bir kopyayla yazacak ve Site Editor özelleştirmelerini iptal edecek. Bu işlem geri alınamaz. Devam edilsin mi?','✓ All parts created.'=>'✓ Tüm parçalar oluşturuldu.','Some parts could not be created.'=>'Bazı parçalar oluşturulamadı.','✓ All translated.'=>'✓ Tüm çeviriler yapıldı.','Some translations failed.'=>'Bazı çeviriler başarısız oldu.','Review carefully — links and slugs not updated.'=>'Dikkatlice incele — bağlantılar ve slug\'lar güncellenmedi.','Fixing…'=>'Düzenleniyor…','✓ Links fixed.'=>'✓ Bağlantılar düzeltildi.','Some link fixes failed.'=>'Bazı bağlantı düzeltmeleri başarısız oldu.','✓ Parts fixed.'=>'✓ Parçalar düzeltildi.','Some part fixes failed.'=>'Bazı parça düzeltmeleri başarısız oldu.','✓ Nav refs fixed.'=>'✓ Navigasyon referansları düzeltildi.','Some nav ref fixes failed.'=>'Bazı navigasyon referansı düzeltmeleri başarısız oldu.','✓ Pattern translated.'=>'✓ Desen çevrildi.','Pattern translation failed.'=>'Desen çevirisi başarısız oldu.','Hide'=>'Gizle','Re-create all templates'=>'Tüm şablonları yeniden oluştur','Re-create all parts'=>'Tüm parçaları yeniden oluştur','This runs Re-create all templates, Re-create all parts, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time. It overwrites existing templates and parts with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template and part, which may take a while and may incur cost depending on your provider. Continue?'=>'Bu, {total} etkin dillerinizin her biri için birer birer "Tüm şablonları yeniden oluştur", "Tüm parçaları yeniden oluştur", "Tümünü çevir", "Tüm parçaları düzelt" ve "Tüm bağlantıları düzelt" işlemlerini çalıştırır. Mevcut şablonları ve parçaları etkin temadan yeni kopyalarla yazacak (Site Editor özelleştirmelerini iptal edecek) ve içeriği yeniden çevirecek — bunların hiçbiri geri alınamaz. "Tümünü çevir" her şablon ve parça için gerçek AI API çağrıları yapacak, bu uzun sürebilir ve sağlayıcınıza bağlı olarak ücret gerektirebilir. Devam edilsin mi?','This runs Re-create all templates, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time — template parts (headers, footers, etc.) are left untouched. It overwrites existing templates with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template, which may take a while and may incur cost depending on your provider. Continue?'=>'Bu, {total} etkin dillerinizin her biri için birer birer "Tüm şablonları yeniden oluştur", "Tümünü çevir", "Tüm parçaları düzelt" ve "Tüm bağlantıları düzelt" işlemlerini çalıştırır — şablon parçaları (başlıklar, altlıklar vb.) değiştirilmez. Mevcut şablonları etkin temadan yeni kopyalarla yazacak (Site Editor özelleştirmelerini iptal edecek) ve içeriği yeniden çevirecek — bunların hiçbiri geri alınamaz. "Tümünü çevir" her şablon için gerçek AI API çağrıları yapacak, bu uzun sürebilir ve sağlayıcınıza bağlı olarak ücret gerektirebilir. Devam edilsin mi?','This runs Re-create all parts (headers, footers, and every other template part) for every one of your {total} active languages, one language at a time. It overwrites existing template parts with fresh copies from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Bu, {total} etkin dillerinizin her biri için birer birer "Tüm parçaları yeniden oluştur" (başlıklar, altlıklar ve diğer tüm şablon parçaları) işlemini çalıştırır. Mevcut şablon parçalarını etkin temadan yeni kopyalarla yazacak ve Site Editor özelleştirmelerini iptal edecek. Bu işlem geri alınamaz. Devam edilsin mi?','Starting…'=>'Başlanıyor…','Processing {lang} ({index} of {total}) — {step}…'=>'{lang} işleniyor ({index}/{total}) — {step}…','Cancelled.'=>'İptal edildi.','{done} of {total} languages processed.'=>'{done}/{total} dil işlendi.','⚠ Done with issues.'=>'⚠ Sorunlarla tamamlandı.','✓ All {total} languages processed.'=>'✓ Tüm {total} dil işlendi.','Built-in preset instructions:'=>'Yerleşik ön ayar talimatları:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Yerleşik talimat yok — her AI özelliği kendi ayarlanmış varsayılanlarını kullanır. Aşağıdaki Özel istem alanını doldurarak kendi site genelinde kurallarınızı ekleyin.','Modified'=>'Değiştirildi','edit'=>'düzenle','No published posts found for the selected filters.'=>'Seçilen filtreler için yayınlanmış gönderi bulunamadı.','Just now'=>'Az önce','Score'=>'Puan','Source title'=>'Kaynak başlık','Multilingual SEO overview'=>'Çok dilli SEO genel bakış','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'Puanlar bir gösterge, karar değil. Bazı içerikler yapısal olarak sınırlıdır — çok kısa sayfalar, az gövde metni içeren açılış sayfaları veya amacı bilgi değil gezinme olan sayfalar doğal olarak daha düşük puan alabilir. Bu genel bakış, diller arasında gerçek eşitlik farklarını tespit etmek içindir, sayıyı takip etmek için değil.','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'Bu, WooCommerce sistem sayfasıdır (Mağaza, Sepet, Ödeme vb.). İçeriği WooCommerce tarafından yönetilir — puan, yalnızca yapısal sinyalleri yansıtır, kullanıcı tarafından düzenlenebilir SEO içeriği değildir.','Settings'=>'Ayarlar','You do not have permission to manage these settings.'=>'Bu ayarları yönetme izniniz yok.','Lingua Forge — Settings'=>'Lingua Forge — Ayarlar','Settings saved.'=>'Ayarlar kaydedildi.','Save Settings'=>'Ayarları Kaydet','Standard'=>'Standart','Technical / Scientific'=>'Teknik / Bilimsel','Legal / Compliance'=>'Yasal / Uyumluluk','Creative / Marketing'=>'Yaratıcı / Pazarlama','Lingua Forge — AI Usage Statistics'=>'Lingua Forge — AI Kullanım İstatistikleri','Lingua Forge AI Usage Statistics'=>'Lingua Forge AI Kullanım İstatistikleri','Date'=>'Tarih','Request count'=>'İstek sayısı','Full Article'=>'Tam Makale','Introduction only'=>'Sadece Giriş','Structured Outline'=>'Yapılandırılmış Taslak','Generate Content'=>'İçerik Oluştur','Hints'=>'İpuçları','Key points, ideas, or structure to build from…'=>'Anahtar noktalar, fikirler veya yapı...','Tone'=>'Ton','Output'=>'Çıktı','Generate Excerpt'=>'Özet Oluştur','Generate Meta Description'=>'Meta Açıklaması Oluştur','Translate Content'=>'İçeriği Çevir','Mode'=>'Mod','Full post'=>'Tam gönderi','Translate chunk'=>'Parçayı çevir','Target Language'=>'Hedef Dil','Text to translate'=>'Çevrilecek metin','Paste a footnote, sentence, or any snippet here…'=>'Buraya bir dipnot, cümle veya herhangi bir parçayı yapıştırın…','Also generate meta description'=>'Ayrıca meta açıklaması oluştur','Translated Labels'=>'Çeviri Etiketleri','Attribute label displayed in this language. Leave empty to use the default label.'=>'Bu dilde görüntülenen öznitelik etiketi. Varsayılan etiketi kullanmak için boş bırakın.','Translate all labels (AI)'=>'Tüm etiketleri çevirin (Yapay Zeka)','Insufficient permissions.'=>'Yetersiz izinler.','All labels already translated.'=>'Tüm etiketler zaten çevrildi.','%d label(s) translated.'=>'%d etiket(ler) çevrildi.','Translation failed. Check the browser console.'=>'Çeviri başarısız oldu. Tarayıcı konsolunu kontrol edin.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Ürün %1$d\'ye yazılamaz: bu çevrilmiş bir sürüm (dil: %2$s)%3$s. İşletme verileri (fiyat, stok, SKU, boyutlar) kaynak üründe güncellenmelidir. Kaynak ürün kimliğini şu yoluyla çözün: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Translated Names'=>'Çevirilen İsimler','Name displayed in this language. Leave empty to use the source name.'=>'Bu dilde görüntülenen isim. Kaynak ismi kullanmak için boş bırakın.','Translate all tags (AI)'=>'Tüm etiketleri çevir (Yapay Zeka)','Translate all categories (AI)'=>'Tüm kategorileri çevirin (Yapay Zeka)','Translate all %s terms (AI)'=>'Tüm %s terimlerini çevirin (Yapay Zeka)','Translate all terms (AI)'=>'Tüm terimleri çevir (Yapay Zeka)','Invalid taxonomy.'=>'Geçersiz taksonomi.','No terms found.'=>'Terim bulunamadı.','%d term(s) translated.'=>'%d terim(ler) çevrildi.','%d already translated — <a href="#" class="lf-force-translate">force retranslate</a>'=>'%d zaten çevrildi — <a href="#" class="lf-force-translate">yeniden çevir</a>','%1$d translated, %2$d skipped.'=>'%1$d çevrildi, %2$d atlandı.','Order placed in language: %s'=>'Sipariş verilen dil: %s','Invalid API key — double-check the key entered in the AI Provider settings.'=>'Geçersiz API anahtarı — AI Sağlayıcı ayarlarında girilen anahtarı tekrar kontrol edin.','Payment required — your account has no remaining credits.'=>'Ödeme gerekli — hesabınızda kalan kredi yok.','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'Erişim yasaklandı — hesabınız askıya alınmış olabilir veya anahtar gerekli izinlere sahip değil.','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'Hız sınırına takıldı — sağlayıcıya çok fazla istek gönderildi; bir süre bekleyin ve tekrar deneyin.','Provider service temporarily unavailable — try again in a moment.'=>'Sağlayıcı hizmeti geçici olarak kullanılamıyor — tekrar deneyin.','Provider error (HTTP %1$d): %2$s'=>'Sağlayıcı hatası (HTTP %1$d): %2$s','Unexpected provider error (HTTP %d).'=>'Beklenmedik sağlayıcı hatası (HTTP %d).','No API key configured — enter your key in the AI Provider settings.'=>'API anahtarı yapılandırılmadı — anahtarınızı AI Sağlayıcı ayarlarına girin.','Network error — could not reach the provider: %s'=>'Ağ hatası — sağlayıcıya ulaşılamadı: %s','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'Kredi kalmadı — OpenAI hesabınızı platform.openai.com/account/billing adresinden yükleyin.','WordPress AI Client requires WordPress 7.0 or later.'=>'WordPress AI İstemcisi, WordPress 7.0 veya sonraki sürümleri gerektirir.','No user message found in the message array.'=>'Mesaj dizisinde kullanıcı mesajı bulunmamaktadır.','No text-generation model is available. Configure an AI provider in Settings → Connectors.'=>'Hiçbir metin üretim modeli bulunmamaktadır. Ayarlar → Bağlayıcılar\'da bir yapay zeka sağlayıcısı yapılandırın.','Too many AI requests. Please retry in %d seconds.'=>'Çok fazla AI isteği. Lütfen %d saniye içinde tekrar deneyin.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Günlük AI kotası aşıldı (%1$d istek). UTC %2$s\'de sıfırlanır.','View Lingua Forge details'=>'Lingua Forge detaylarını görüntüle','View details'=>'Detayları görüntüle','Visit plugin site'=>'Eklenti sitesini ziyaret et','Lingua Forge update blocked: download host "%s" is not on the allowlist.'=>'Lingua Forge güncellemesi engellendi: indirme ana bilgisayar "%s" izin listesinde değil.','Lingua Forge update blocked: SHA-256 of the downloaded package does not match the manifest. The file may have been tampered with.'=>'Lingua Forge güncellemesi engellendi: İndirilen paketin SHA-256 değeri manifest ile eşleşmiyor. Dosya değiştirilmiş olabilir.','Exclude from navigation menus'=>'Gezinti menülerinden hariç tut','Apply to all language versions'=>'Tüm dil sürümlerine uygula','Noindex (hide this language version from search engines)'=>'Noindex (bu dil sürümünü arama motorlarından gizle)','%d language not yet linked'=>'%d dil henüz bağlantılı değil' . "\0" . '%d dil henüz bağlantılı değil','This is the source page. Footnotes are edited directly in the block editor.'=>'Bu kaynak sayfa. Dipnotlar doğrudan blok düzenleyicide düzenlenir.','No source page linked yet.'=>'Henüz kaynak sayfa bağlantısı yok.','The source page has no footnotes.'=>'Kaynak sayfada dipnot yok.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Bu dipnotlar kaynak sayfadan gelir ve burada sadece referans olarak gösterilir. Bunları blok düzenleyici kullanarak bu sayfaya ekleyin.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d yerelleştirilmiş şablon(lar) &#8220;%2$s&#8221; temasından veritabanında korunuyor, ancak şu anda etkin değil. Bu temayı yeniden etkinleştirirseniz, tekrar aktif hale gelirler. Çevirilerinizi yeni temaya taşımak için, <strong>Ayarlar → Lingua Forge → Yönlendirici → FSE iskeleti</strong> aracılığıyla yeniden oluşturun.','Scanning posts for missing or out-of-sync featured images…'=>'Yazılar eksik veya senkronizasyonu bozuk öne çıkan görseller açısından taranıyor…','Re-scanning…'=>'Tekrar tarama…','Scan failed: '=>'Tarama başarısız: ','unknown error'=>'bilinmeyen hata','Scan request failed. Please try again.'=>'Tarama isteği başarısız oldu. Lütfen tekrar deneyin.','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ <strong>{lang}</strong> gönderisi bulunamadı. Tüm çevrilmiş gönderilerin Dil meta kutusunda <strong>{lang}</strong> olarak ayarlandığından emin olun.','✅ All <strong>{lang}</strong> featured images are already in sync with their source post. Scanned <strong>{scanned}</strong> post(s).'=>'✅ Tüm <strong>{lang}</strong> öne çıkan görseller, kaynak gönderileriyle zaten senkronizedir. Tarandı <strong>{scanned}</strong> gönderi(ler).','Found <strong>{n}</strong> post(s) missing or 